 56	// 解析模式字符串
 57	client_mode_t parse_mode(const char* mode_str) {
 58	 if (strcmp(mode_str, "SHARED_MEMORY") == 0) {
 59	 return CLIENT_MODE_SHARED_MEMORY;
 60	 } else if (strcmp(mode_str, "UNIX_SOCKET") == 0) {
 61	 return CLIENT_MODE_UNIX_SOCKET;
 62	 } else if (strcmp(mode_str, "TCP_SOCKET") == 0) {
 63	 return CLIENT_MODE_TCP_SOCKET;
 64	 } else {
 65	 return CLIENT_MODE_TCP_SOCKET; // 默认
 66	 }
 67	}
 68	
 69	// 解析等号格式的参数
 70	int parse_argument(const char* arg, const char* prefix, char* value, size_t value_size) {
 71	 size_t prefix_len = strlen(prefix);
 72	 if (strncmp(arg, prefix, prefix_len) == 0 && arg[prefix_len] == '=') {
 73	 strncpy(value, arg + prefix_len + 1, value_size - 1);
 74	 value[value_size - 1] = '\0';
 75	 return 1;
 76	 }
 77	 return 0;
 78	}
 79	
 80	// 解析等号格式的整数参数
 81	int parse_int_argument(const char* arg, const char* prefix, int* value) {
 82	 char str_value[64];
 83	 if (parse_argument(arg, prefix, str_value, sizeof(str_value))) {
 84	 *value = atoi(str_value);
 85	 return 1;
 86	 }
 87	 return 0;
 88	}
