 115	// 主函数
 116	int main(int argc, char* argv[]) {
 117	 // 初始化OpenCV
 118	 if (opencv_init() != 0) {
 119	 printf("警告: OpenCV初始化失败，将使用传统方法保存图片\n");
 120	 }
 121	
 122	 // 默认配置
 123	 client_mode_t mode = CLIENT_MODE_TCP_SOCKET;
 124	 char tcp_host[256] = "127.0.0.1";
 125	 int tcp_port = 7777;
 126	 char socket_name[256] = "server-k";
 127	 int memory_size = 1024 * 1024; // 1MB
 128	 int continuous = 0;
 129	 int interval = 1;
 130	 char output_prefix[256] = "screenshot";
 131	 
 132	 // 解析命令行参数
 133	 for (int i = 1; i < argc; i++) {
 134	 char value[256];
 135	 
 136	 if (parse_argument(argv[i], "--mode", value, sizeof(value))) {
 137	 mode = parse_mode(value);
 138	 } else if (parse_argument(argv[i], "--tcpHost", value, sizeof(value))) {
 139	 strncpy(tcp_host, value, sizeof(tcp_host) - 1);
 140	 } else if (parse_int_argument(argv[i], "--tcpPort", &tcp_port)) {
 141	 if (tcp_port <= 0 || tcp_port > 65535) {
 142	 printf("错误: 无效的端口号 %d\n", tcp_port);
 143	 return 1;
 144	 }
 145	 } else if (parse_argument(argv[i], "--socketName", value, sizeof(value))) {
 146	 strncpy(socket_name, value, sizeof(socket_name) - 1);
 147	 } else if (parse_int_argument(argv[i], "--memorySize", &memory_size)) {
 148	 if (memory_size <= 0) {
 149	 printf("错误: 无效的内存大小 %d\n", memory_size);
 150	 return 1;
 151	 }
 152	 } else if (strcmp(argv[i], "--continuous") == 0) {
 153	 continuous = 1;
 154	 } else if (parse_int_argument(argv[i], "--interval", &interval)) {
 155	 if (interval <= 0) {
 156	 printf("错误: 无效的间隔时间 %d\n", interval);
 157	 return 1;
 158	 }
 159	 } else if (parse_argument(argv[i], "--output", value, sizeof(value))) {
 160	 strncpy(output_prefix, value, sizeof(output_prefix) - 1);
 161	 } else if (strcmp(argv[i], "--debug") == 0) {
 162	 debug_mode = 1;
 163	 } else if (strcmp(argv[i], "--help") == 0) {
 164	 print_usage(argv[0]);
 165	 return 0;
 166	 } else if (strcmp(argv[i], "--version") == 0) {
 167	 print_version();
 168	 return 0;
 169	 } else {
 170	 printf("未知参数: %s\n", argv[i]);
 171	 printf("使用 --help 查看帮助信息\n");
 172	 return 1;
 173	 }
 174	 }
 175	 
 176	 // 设置信号处理
 177	 signal(SIGINT, signal_handler);
 178	 signal(SIGTERM, signal_handler);
 179	 
 180	 // 打印配置信息
 181	 if (debug_mode) {
 182	 printf("[DEBUG] === Server-K 客户端 v%s ===\n", VERSION);
 183	 } else {
 184	 printf("=== Server-K 客户端 v%s ===\n", VERSION);
 185	 }
 186	 
 187	 const char* mode_names[] = {"共享内存", "Unix套接字", "TCP套接字"};
 188	 printf("通信模式: %s\n", mode_names[mode]);
 189	 
 190	 switch (mode) {
 191	 case CLIENT_MODE_TCP_SOCKET:
 192	 printf("服务器地址: %s:%d\n", tcp_host, tcp_port);
 193	 break;
 194	 case CLIENT_MODE_UNIX_SOCKET:
 195	 printf("套接字名称: %s\n", socket_name);
 196	 break;
 197	 case CLIENT_MODE_SHARED_MEMORY:
 198	 printf("内存大小: %d 字节\n", memory_size);
 199	 break;
 200	 }
 201	 
 202	 if (continuous) {
 203	 printf("连续截图模式: 间隔 %d 秒\n", interval);
 204	 }
 205	 printf("输出前缀: %s\n", output_prefix);
 206	 printf("调试模式: %s\n", debug_mode ? "开启" : "关闭");
 207	 printf("================================\n\n");
 208	 
 209	 // 初始化客户端
 210	 if (debug_mode) {
 211	 printf("[DEBUG] 正在初始化客户端...\n");
 212	 } else {
 213	 printf("正在初始化客户端...\n");
 214	 }
 215	 
 216	 int result = client_initialize_with_params(mode, memory_size, socket_name, tcp_host, tcp_port);
 217	 if (result != 0) {
 218	 printf("错误: 客户端初始化失败 (错误代码: %d)\n", result);
 219	 return 1;
 220	 }
 221	 
 222	 // 连接服务器
 223	 if (debug_mode) {
 224	 printf("[DEBUG] 正在连接服务器...\n");
 225	 } else {
 226	 printf("正在连接服务器...\n");
 227	 }
 228	 
 229	 result = client_connect();
 230	 if (result != 0) {
 231	 printf("错误: 连接服务器失败 (错误代码: %d)\n", result);
 232	 client_disconnect();
 233	 return 1;
 234	 }
 235	 
 236	 printf("✅ 连接成功！\n\n");
 237	 
 238	 // 截图循环
 239	 int screenshot_count = 0;
 240	 while (g_running) {
 241	 if (debug_mode) {
 242	 printf("[DEBUG] 正在截图 #%d...\n", screenshot_count + 1);
 243	 } else {
 244	 printf("正在截图 #%d...\n", screenshot_count + 1);
 245	 }
 246	 
 247	 client_response_t* response = client_take_screenshot();
 248	 if (response) {
 249	 if (response->success && response->data && response->data_size > 0) {
 250	 // 生成文件名
 251	 char filename[512];
 252	 if (continuous) {
 253	 snprintf(filename, sizeof(filename), "%s_%04d", output_prefix, screenshot_count + 1);
 254	 } else {
 255	 snprintf(filename, sizeof(filename), "%s", output_prefix);
 256	 }
 257	 
 258	 // 保存文件
 259	 if (save_screenshot(response->data, response->data_size, filename) == 0) {
 260	 if (debug_mode) {
 261	 printf("[DEBUG] ✅ 截图成功! 耗时: %ld ms\n", response->processing_time);
 262	 } else {
 263	 printf("✅ 截图成功! 耗时: %ld ms\n", response->processing_time);
 264	 }
 265	 screenshot_count++;
 266	 } else {
 267	 printf("❌ 保存文件失败\n");
 268	 }
 269	 } else {
 270	 printf("❌ 截图失败: %s\n", response->message);
 271	 }
 272	 
 273	 if (debug_mode && response->message[0]) {
 274	 printf("[DEBUG] 详细信息: %s\n", response->message);
 275	 }
 276	 
 277	 free_client_response(response);
 278	 } else {
 279	 printf("❌ 截图响应为空\n");
 280	 }
 281	 
 282	 if (!continuous) {
 283	 break;
 284	 }
 285	 
 286	 printf("\n");
 287	 
 288	 // 等待间隔时间
 289	 for (int i = 0; i < interval && g_running; i++) {
 290	 sleep(1);
 291	 }
 292	 }
 293	 
 294	 // 清理资源
 295	 if (debug_mode) {
 296	 printf("\n[DEBUG] 正在断开连接...\n");
 297	 } else {
 298	 printf("\n正在断开连接...\n");
 299	 }
 300	 client_disconnect();
 301	 
 302	 if (debug_mode) {
 303	 printf("[DEBUG] 总共完成 %d 次截图\n", screenshot_count);
 304	 printf("[DEBUG] 程序退出\n");
 305	 } else {
 306	 printf("总共完成 %d 次截图\n", screenshot_count);
 307	 printf("程序退出\n");
 308	 }
 309	
 310	 // 清理OpenCV资源
 311	 opencv_cleanup();
 312	
 313	 return 0;
 314	}
