 69	/**
 70	 * 查找Android NDK路径
 71	 */
 72	fun findAndroidNdk(): String {
 73	 // 1. 检查环境变量
 74	 val ndkFromEnv = System.getenv("ANDROID_NDK") ?: System.getenv("ANDROID_NDK_ROOT")
 75	 if (ndkFromEnv != null && File(ndkFromEnv).exists()) {
 76	 return ndkFromEnv
 77	 }
 78	 // 2. 从Android SDK路径查找
 79	 val androidHome = System.getenv("ANDROID_HOME") ?: System.getenv("ANDROID_SDK_ROOT")
 80	 if (androidHome != null) {
 81	 val ndkDir = File(androidHome, "ndk")
 82	 if (ndkDir.exists()) {
 83	 // 查找最新版本的NDK
 84	 val ndkVersions = ndkDir.listFiles()?.filter {
 85	 it.isDirectory && it.name.matches(Regex("\\d+\\..*"))
 86	 }?.sortedByDescending { it.name }
 87	
 88	 if (ndkVersions?.isNotEmpty() == true) {
 89	 return ndkVersions.first().absolutePath
 90	 }
 91	 }
 92	 }
 93	 throw GradleException("未找到Android NDK。请设置环境变量 ANDROID_NDK 或 ANDROID_NDK_ROOT")
 94	}
 95	
 96	/**
 97	 * 查找dx工具路径
 98	 */
 99	fun findDxTool(androidHome: String): String {
 100	 // 新版本的dx工具路径
 101	 val newDxPath = File(androidHome, "build-tools").listFiles()
 102	 ?.filter { it.isDirectory && it.name.matches(Regex("\\d+\\..*")) }
 103	 ?.maxByOrNull { it.name }
 104	 ?.let { File(it, "dx") }
 105	 if (newDxPath?.exists() == true) {
 106	 return newDxPath.absolutePath
 107	 }
 108	 // 旧版本的dx工具路径
 109	 val oldDxPath = File(androidHome, "platform-tools/dx")
 110	 if (oldDxPath.exists()) {
 111	 return oldDxPath.absolutePath
 112	 }
 113	 // 在build-tools中查找任何版本的dx
 114	 val buildToolsDir = File(androidHome, "build-tools")
 115	 if (buildToolsDir.exists()) {
 116	 buildToolsDir.listFiles()?.forEach { versionDir ->
 117	 if (versionDir.isDirectory) {
 118	 val dxFile = File(versionDir, "dx")
 119	 if (dxFile.exists()) {
 120	 return dxFile.absolutePath
 121	 }
 122	 }
 123	 }
 124	 }
 125	
 126	 throw GradleException("未找到dx工具，请检查Android SDK安装")
 127	}
