 187	/**
 188	 * 生成客户端专用的CMakeLists.txt内容（支持OpenCV）
 189	 */
 190	fun generateClientCMakeContent(sourceDir: File, binDir: File): String {
 191	 return """
 192	cmake_minimum_required(VERSION 3.22.1)
 193	
 194	project("k-client" C CXX)
 195	
 196	# 设置C标准
 197	set(CMAKE_C_STANDARD 99)
 198	set(CMAKE_C_STANDARD_REQUIRED ON)
 199	
 200	# 设置C++标准
 201	set(CMAKE_CXX_STANDARD 17)
 202	set(CMAKE_CXX_STANDARD_REQUIRED ON)
 203	
 204	# 添加编译选项
 205	add_compile_options(-Wall -Wextra -Wno-unused-parameter -Wno-unused-function -O2)
 206	
 207	# 定义宏，禁用Android和JNI相关代码
 208	add_definitions(-UANDROID -U__ANDROID__ -DDISABLE_JNI)
 209	
 210	# 设置OpenCV路径
 211	set(OpenCV_DIR "${sourceDir.absolutePath}/client/opencv")
 212	set(OpenCV_INCLUDE_DIRS "${sourceDir.absolutePath}/client/opencv/include")
 213	set(OpenCV_STATIC_LIBS_DIR "${sourceDir.absolutePath}/client/opencv/libs")
 214	
 215	# 包含OpenCV头文件
 216	include_directories(${'$'}{OpenCV_INCLUDE_DIRS})
 217	
 218	# 手动设置OpenCV库（按依赖顺序）
 219	set(OpenCV_LIBS
 220	 ${'$'}{OpenCV_STATIC_LIBS_DIR}/libopencv_imgcodecs.a
 221	 ${'$'}{OpenCV_STATIC_LIBS_DIR}/libopencv_imgproc.a
 222	 ${'$'}{OpenCV_STATIC_LIBS_DIR}/libopencv_core.a
 223	)
 224	
 225	# 添加第三方依赖库
 226	set(OpenCV_3RDPARTY_LIBS_DIR "${sourceDir.absolutePath}/client/opencv/3rdparty")
 227	set(OpenCV_3RDPARTY_LIBS
 228	 ${'$'}{OpenCV_3RDPARTY_LIBS_DIR}/libtegra_hal.a
 229	 ${'$'}{OpenCV_3RDPARTY_LIBS_DIR}/libtbb.a
 230	 ${'$'}{OpenCV_3RDPARTY_LIBS_DIR}/libittnotify.a
 231	 ${'$'}{OpenCV_3RDPARTY_LIBS_DIR}/liblibjpeg-turbo.a
 232	 ${'$'}{OpenCV_3RDPARTY_LIBS_DIR}/liblibpng.a
 233	 ${'$'}{OpenCV_3RDPARTY_LIBS_DIR}/liblibwebp.a
 234	 ${'$'}{OpenCV_3RDPARTY_LIBS_DIR}/liblibtiff.a
 235	 ${'$'}{OpenCV_3RDPARTY_LIBS_DIR}/libIlmImf.a
 236	 ${'$'}{OpenCV_3RDPARTY_LIBS_DIR}/liblibopenjp2.a
 237	)
 238	
 239	message(STATUS "✅ Using local OpenCV Android SDK")
 240	message(STATUS "OpenCV include dirs: ${'$'}{OpenCV_INCLUDE_DIRS}")
 241	message(STATUS "OpenCV static libs: ${'$'}{OpenCV_STATIC_LIBS_DIR}")
 242	message(STATUS "OpenCV libraries: ${'$'}{OpenCV_LIBS}")
 243	
 244	# 创建客户端可执行文件
 245	add_executable(k-client
 246	 ${sourceDir.absolutePath}/client/main.c
 247	 ${sourceDir.absolutePath}/client/client_opencv.cpp
 248	 ${sourceDir.absolutePath}/client/core/client_core.c
 249	 ${sourceDir.absolutePath}/client/transport/client_shared_memory.c
 250	 ${sourceDir.absolutePath}/client/transport/client_unix.c
 251	 ${sourceDir.absolutePath}/client/transport/client_tcp.c
 252	 ${sourceDir.absolutePath}/common/ashmem.c
 253	 ${sourceDir.absolutePath}/common/log.c
 254	)
 255	
 256	# 链接OpenCV静态库和依赖库
 257	target_link_libraries(k-client ${'$'}{OpenCV_LIBS} ${'$'}{OpenCV_3RDPARTY_LIBS})
 258	
 259	# 链接Android系统库
 260	if(ANDROID)
 261	 find_library(log-lib log)
 262	 find_library(z-lib z)
 263	 if(log-lib)
 264	 target_link_libraries(k-client ${'$'}{log-lib})
 265	 endif()
 266	 if(z-lib)
 267	 target_link_libraries(k-client ${'$'}{z-lib})
 268	 endif()
 269	 # Android上pthread是内置的，不需要单独链接
 270	else()
 271	 find_library(pthread-lib pthread)
 272	 if(pthread-lib)
 273	 target_link_libraries(k-client ${'$'}{pthread-lib})
 274	 else()
 275	 target_link_libraries(k-client pthread)
 276	 endif()
 277	endif()
 278	
 279	# 链接C++标准库
 280	target_link_libraries(k-client -static-libstdc++)
 281	
 282	# 设置输出目录
 283	set_target_properties(k-client PROPERTIES
 284	 RUNTIME_OUTPUT_DIRECTORY "${binDir.absolutePath}"
 285	)
 286	""".trimIndent()
 287	}
