 289	/**
 290	 * 生成服务器专用的CMakeLists.txt内容
 291	 */
 292	fun generateServerCMakeContent(sourceDir: File, binDir: File): String {
 293	 return """
 294	cmake_minimum_required(VERSION 3.22.1)
 295	
 296	project("server-k-server" C)
 297	
 298	# 设置C标准
 299	set(CMAKE_C_STANDARD 99)
 300	
 301	# 添加编译选项
 302	add_compile_options(-Wall -Wextra -Wno-unused-parameter -Wno-unused-function -O2)
 303	
 304	# 创建服务器共享库（只包含服务器功能，不包含客户端）
 305	add_library(server-k SHARED
 306	 ${sourceDir.absolutePath}/server/core/server_core.c
 307	 ${sourceDir.absolutePath}/server/jni/server_jni_bridge.c
 308	 ${sourceDir.absolutePath}/server/transport/server_shared_memory.c
 309	 ${sourceDir.absolutePath}/server/transport/server_unix.c
 310	 ${sourceDir.absolutePath}/server/transport/server_tcp.c
 311	 ${sourceDir.absolutePath}/common/ashmem.c
 312	 ${sourceDir.absolutePath}/common/log.c
 313	)
 314	
 315	# 链接Android日志库
 316	if(ANDROID)
 317	 find_library(log-lib log)
 318	 if(log-lib)
 319	 target_link_libraries(server-k ${'$'}{log-lib})
 320	 endif()
 321	endif()
 322	
 323	# 在Android上，pthread功能内置在libc中，不需要单独链接
 324	# 只在非Android平台上链接pthread库
 325	if(NOT ANDROID)
 326	 find_library(pthread-lib pthread)
 327	 if(pthread-lib)
 328	 target_link_libraries(server-k ${'$'}{pthread-lib})
 329	 else()
 330	 target_link_libraries(server-k pthread)
 331	 endif()
 332	endif()
 333	
 334	# 设置输出目录
 335	set_target_properties(server-k PROPERTIES
 336	 LIBRARY_OUTPUT_DIRECTORY "${binDir.absolutePath}"
 337	)
 338	""".trimIndent()
 339	}
