 341	// ================================
 342	// 服务器程序构建任务
 343	// ================================
 344	
 345	/**
 346	 * 构建服务器程序，产出server-k-server.dex和libserver-k.so
 347	 */
 348	tasks.register("buildServer") {
 349	 group = "server"
 350	 description = "构建服务器程序，产出k-server.dex和libserver-k.so"
 351	 // 依赖Java编译任务
 352	 dependsOn("compileDebugJavaWithJavac")
 353	 doLast {
 354	 val projectRoot = project.rootDir
 355	 val sourceDir = File(projectRoot, "server-k/src/main/cpp")
 356	 val buildDir = File(projectRoot, "build/server-android")
 357	 val binDir = File(projectRoot, "build/bin-server")
 358	 val outputDir = File(projectRoot, "server-k/build/k-server-output")
 359	 val libDir = File(outputDir, "lib/arm64-v8a")
 360	 println("=== 构建服务器程序 ===")
 361	 println("源码目录: ${sourceDir.absolutePath}")
 362	 println("构建目录: ${buildDir.absolutePath}")
 363	 println("输出目录: ${outputDir.absolutePath}")
 364	 // 检查源码目录
 365	 if (!sourceDir.exists()) {
 366	 throw GradleException("源码目录不存在: ${sourceDir.absolutePath}")
 367	 }
 368	 // 清理并创建构建目录
 369	 if (buildDir.exists()) {
 370	 buildDir.deleteRecursively()
 371	 }
 372	 buildDir.mkdirs()
 373	 binDir.mkdirs()
 374	 outputDir.mkdirs()
 375	 libDir.mkdirs()
 376	 // 检查Android NDK
 377	 val androidNdk = findAndroidNdk()
 378	 println("使用NDK: $androidNdk")
 379	 // 创建服务器专用的CMakeLists.txt
 380	 val serverCMakeFile = File(buildDir, "CMakeLists.txt")
 381	 serverCMakeFile.writeText(generateServerCMakeContent(sourceDir, binDir))
 382	 // 查找CMake路径
 383	 val cmakePath = findCMakePath()
 384	 println("使用CMake: $cmakePath")
 385	 // 配置CMake
 386	 val cmakeConfigCmd = listOf(
 387	 cmakePath,
 388	 buildDir.absolutePath,
 389	 "-DCMAKE_TOOLCHAIN_FILE=$androidNdk/build/cmake/android.toolchain.cmake",
 390	 "-DANDROID_ABI=arm64-v8a",
 391	 "-DANDROID_PLATFORM=android-24",
 392	 "-DCMAKE_BUILD_TYPE=Release"
 393	 )
 394	 println("配置CMake...")
 395	 val configResult = project.exec {
 396	 workingDir = buildDir
 397	 commandLine = cmakeConfigCmd
 398	 isIgnoreExitValue = true
 399	 }
 400	 if (configResult.exitValue != 0) {
 401	 throw GradleException("CMake配置失败")
 402	 }
 403	 // 编译
 404	 println("开始编译...")
 405	 val buildResult = project.exec {
 406	 workingDir = buildDir
 407	 commandLine = listOf("make", "-j${Runtime.getRuntime().availableProcessors()}")
 408	 isIgnoreExitValue = true
 409	 }
 410	 if (buildResult.exitValue != 0) {
 411	 throw GradleException("编译失败")
 412	 }
 413	 // 1. 复制SO库文件
 414	 val serverBinary = File(binDir, "libserver-k.so")
 415	 if (serverBinary.exists()) {
 416	 val targetFile = File(libDir, "libserver-k.so")
 417	 serverBinary.copyTo(targetFile, overwrite = true)
 418	 println("✅ 复制SO库: ${serverBinary.name} -> ${targetFile.absolutePath}")
 419	 println(" 文件大小: ${targetFile.length()} 字节")
 420	 } else {
 421	 throw GradleException("未找到生成的SO文件: ${serverBinary.absolutePath}")
 422	 }
 423	 // 2. 创建服务器专用的DEX文件
 424	 val classesDir = File(
 425	 projectRoot,
 426	 "server-k/build/intermediates/javac/debug/compileDebugJavaWithJavac/classes"
 427	 )
 428	 val dexFile = File(outputDir, "k-server.dex")
 429	 if (classesDir.exists()) {
 430	 // 使用dx工具创建DEX文件
 431	 val androidHome = System.getenv("ANDROID_HOME") ?: System.getenv("ANDROID_SDK_ROOT")
 432	 if (androidHome == null) {
 433	 throw GradleException("未找到Android SDK，请设置ANDROID_HOME或ANDROID_SDK_ROOT环境变量")
 434	 }
 435	
 436	 // 查找dx工具
 437	 val dxTool = findDxTool(androidHome)
 438	 println("使用DX工具: $dxTool")
 439	
 440	 // 收集所有需要的类文件和依赖
 441	 val classpath = mutableListOf<String>()
 442	
 443	 // 添加项目类文件
 444	 classpath.add(classesDir.absolutePath)
 445	
 446	 // 添加依赖的JAR文件（过滤掉有问题的文件）
 447	 configurations.getByName("debugRuntimeClasspath").files.forEach { file ->
 448	 if (file.name.endsWith(".jar") &&
 449	 !file.name.contains("kotlin-stdlib") &&
 450	 !file.name.contains("gson") &&
 451	 !file.name.contains("annotations")
 452	 ) {
 453	 classpath.add(file.absolutePath)
 454	 println("添加依赖: ${file.name}")
 455	 } else {
 456	 println("跳过JAR: ${file.name}")
 457	 }
 458	 }
 459	
 460	 // 执行dx命令
 461	 val dxCmd = listOf(
 462	 dxTool,
 463	 "--dex",
 464	 "--min-sdk-version=24",
 465	 "--output=${dexFile.absolutePath}"
 466	 ) + classpath
 467	
 468	 println("创建DEX文件...")
 469	 val dxResult = project.exec {
 470	 commandLine = dxCmd
 471	 isIgnoreExitValue = true
 472	 }
 473	
 474	 if (dxResult.exitValue != 0) {
 475	 throw GradleException("创建DEX文件失败")
 476	 }
 477	
 478	 if (dexFile.exists()) {
 479	 println("✅ 创建DEX文件: ${dexFile.absolutePath}")
 480	 println(" 文件大小: ${dexFile.length()} 字节")
 481	 } else {
 482	 throw GradleException("DEX文件创建失败")
 483	 }
 484	 } else {
 485	 throw GradleException("Java类文件目录不存在: ${classesDir.absolutePath}")
 486	 }
 487	
 488	 // 4. 显示使用说明
 489	 println("\n=== 服务器构建完成 ===")
 490	 println(" 输出目录: ${outputDir.absolutePath}")
 491	 println(" 输出文件:")
 492	 println(" - k-server.dex: ${dexFile.length()} 字节")
 493	 println(" - libserver-k.so: ${File(libDir, "libserver-k.so").length()} 字节")
 494	 println()
 495	 println(" 部署到设备:")
 496	 println(" adb push ${outputDir.absolutePath}/* /data/local/tmp/")
 497	 println()
 498	 println("▶️ 启动服务器:")
 499	 println(" adb shell 'chmod +x /data/local/tmp/k-server.dex && chmod +x /data/local/tmp/lib/arm64-v8a/libserver-k.so && CLASSPATH=/data/local/tmp/k-server.dex app_process /system/bin com.github.kirer.server.Launcher --mode=TCP_SOCKET --libPath=/data/local/tmp/lib/arm64-v8a --tcpHost=127.0.0.1 --tcpPort=7777 --debug > /data/local/tmp/k-server.log 2>&1 &'")
 500	 println()
 501	 }
 502	}
