 30	void* server_thread_func(void* arg) {
 31	 (void)arg; // 抑制未使用参数警告
 32	
 33	 LOG_INFO(SERVER_LOG_TAG, "服务器线程已启动");
 34	
 35	 const server_ops_t* ops = get_server_ops(g_server_ctx.config.mode);
 36	 if (!ops) {
 37	 LOG_ERROR(SERVER_LOG_TAG, "获取服务器操作函数失败");
 38	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 39	 g_server_ctx.state = SERVER_STATE_ERROR;
 40	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 41	 return NULL;
 42	 }
 43	
 44	 // 启动服务器
 45	 if (ops->start() != 0) {
 46	 LOG_ERROR(SERVER_LOG_TAG, "启动服务器失败");
 47	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 48	 g_server_ctx.state = SERVER_STATE_ERROR;
 49	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 50	 return NULL;
 51	 }
 52	
 53	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 54	 g_server_ctx.state = SERVER_STATE_STARTED;
 55	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 56	
 57	 LOG_INFO(SERVER_LOG_TAG, "服务器启动成功");
 58	
 59	 // 保持线程运行
 60	 while (g_server_ctx.thread_running) {
 61	 usleep(100000); // 100ms
 62	 }
 63	
 64	 LOG_INFO(SERVER_LOG_TAG, "服务器线程正在停止");
 65	
 66	 // 停止服务器
 67	 if (ops->stop() != 0) {
 68	 LOG_WARN(SERVER_LOG_TAG, "停止服务器时发生错误");
 69	 }
 70	
 71	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 72	 g_server_ctx.state = SERVER_STATE_STOPPED;
 73	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 74	
 75	 LOG_INFO(SERVER_LOG_TAG, "服务器线程已停止");
 76	 return NULL;
 77	}
