 79	// 初始化服务器（参数配置）
 80	int server_initialize_with_params(server_mode_t mode, int memory_size, const char* lib_path,
 81	 const char* socket_name, const char* tcp_host, int tcp_port) {
 82	 LOG_INFO(SERVER_LOG_TAG, "使用参数配置初始化服务器");
 83	
 84	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 85	 if (g_server_ctx.state != SERVER_STATE_UNINITIALIZED) {
 86	 LOG_WARN(SERVER_LOG_TAG, "服务器已初始化");
 87	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 88	 return 0;
 89	 }
 90	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 91	
 92	 // 设置配置
 93	 memset(&g_server_ctx.config, 0, sizeof(server_config_t));
 94	 g_server_ctx.config.mode = mode;
 95	 g_server_ctx.config.memory_size = memory_size;
 96	 g_server_ctx.config.tcp_port = tcp_port;
 97	
 98	 if (lib_path) {
 99	 strncpy(g_server_ctx.config.lib_path, lib_path, sizeof(g_server_ctx.config.lib_path) - 1);
 100	 }
 101	 if (socket_name) {
 102	 strncpy(g_server_ctx.config.socket_name, socket_name, sizeof(g_server_ctx.config.socket_name) - 1);
 103	 } else {
 104	 strcpy(g_server_ctx.config.socket_name, "server-k");
 105	 }
 106	 if (tcp_host) {
 107	 strncpy(g_server_ctx.config.tcp_host, tcp_host, sizeof(g_server_ctx.config.tcp_host) - 1);
 108	 } else {
 109	 strcpy(g_server_ctx.config.tcp_host, "127.0.0.1");
 110	 }
 111	
 112	 // 初始化互斥锁
 113	 if (pthread_mutex_init(&g_server_ctx.state_mutex, NULL) != 0) {
 114	 LOG_ERROR(SERVER_LOG_TAG, "初始化状态互斥锁失败");
 115	 return -1;
 116	 }
 117	
 118	 // 获取服务器操作函数并初始化
 119	 const server_ops_t* ops = get_server_ops(g_server_ctx.config.mode);
 120	 if (!ops || ops->initialize(&g_server_ctx.config) != 0) {
 121	 LOG_ERROR(SERVER_LOG_TAG, "初始化服务器实现失败");
 122	 pthread_mutex_destroy(&g_server_ctx.state_mutex);
 123	 return -1;
 124	 }
 125	
 126	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 127	 g_server_ctx.state = SERVER_STATE_INITIALIZED;
 128	 g_server_ctx.thread_running = false;
 129	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 130	
 131	 LOG_INFO(SERVER_LOG_TAG, "使用参数配置的服务器初始化成功");
 132	 return 0;
 133	}
 134	
 135	// 启动服务器
 136	int server_start(void) {
 137	 LOG_INFO(SERVER_LOG_TAG, "启动服务器");
 138	
 139	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 140	 if (g_server_ctx.state != SERVER_STATE_INITIALIZED) {
 141	 LOG_ERROR(SERVER_LOG_TAG, "服务器未初始化或已启动");
 142	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 143	 return -1;
 144	 }
 145	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 146	
 147	 // 启动服务器线程
 148	 g_server_ctx.thread_running = true;
 149	 if (pthread_create(&g_server_ctx.server_thread, NULL, server_thread_func, NULL) != 0) {
 150	 LOG_ERROR(SERVER_LOG_TAG, "创建服务器线程失败");
 151	 g_server_ctx.thread_running = false;
 152	 return -1;
 153	 }
 154	
 155	 // 等待服务器启动
 156	 int timeout = 50; // 5秒超时
 157	 while (timeout > 0) {
 158	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 159	 server_state_t state = g_server_ctx.state;
 160	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 161	
 162	 if (state == SERVER_STATE_STARTED) {
 163	 LOG_INFO(SERVER_LOG_TAG, "服务器启动成功");
 164	 return 0;
 165	 } else if (state == SERVER_STATE_ERROR) {
 166	 LOG_ERROR(SERVER_LOG_TAG, "服务器启动失败");
 167	 g_server_ctx.thread_running = false;
 168	 pthread_join(g_server_ctx.server_thread, NULL);
 169	 return -1;
 170	 }
 171	
 172	 usleep(100000); // 100ms
 173	 timeout--;
 174	 }
 175	
 176	 LOG_ERROR(SERVER_LOG_TAG, "服务器启动超时");
 177	 g_server_ctx.thread_running = false;
 178	 pthread_join(g_server_ctx.server_thread, NULL);
 179	 return -1;
 180	}
 181	
 182	// 停止服务器
 183	int server_stop(void) {
 184	 LOG_INFO(SERVER_LOG_TAG, "停止服务器");
 185	
 186	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 187	 server_state_t state = g_server_ctx.state;
 188	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 189	
 190	 if (state != SERVER_STATE_STARTED) {
 191	 LOG_WARN(SERVER_LOG_TAG, "服务器未启动");
 192	 return 0;
 193	 }
 194	
 195	 // 停止服务器线程
 196	 g_server_ctx.thread_running = false;
 197	 if (pthread_join(g_server_ctx.server_thread, NULL) != 0) {
 198	 LOG_WARN(SERVER_LOG_TAG, "等待服务器线程结束失败");
 199	 }
 200	
 201	 // 清理资源
 202	 cleanup_server_resources();
 203	
 204	 pthread_mutex_lock(&g_server_ctx.state_mutex);
 205	 g_server_ctx.state = SERVER_STATE_STOPPED;
 206	 pthread_mutex_unlock(&g_server_ctx.state_mutex);
 207	
 208	 LOG_INFO(SERVER_LOG_TAG, "服务器停止成功");
 209	 return 0;
 210	}
