 37	 printf(" --continuous 连续截图模式\n");
 38	 printf(" --interval=SECONDS 截图间隔秒数 (默认: 1)\n");
 39	 printf(" --output=FILE 输出文件前缀 (默认: screenshot)\n");
 40	 printf(" --debug 调试模式\n");
 41	 printf(" --help 显示此帮助信息\n");
 42	 printf(" --version 显示版本信息\n");
 43	 printf("\n示例:\n");
 44	 printf(" %s --mode=TCP_SOCKET --tcpHost=127.0.0.1 --tcpPort=7777 --debug\n", program_name);
 45	 printf(" %s --mode=UNIX_SOCKET --socketName=my-server\n", program_name);
 46	 printf(" %s --mode=SHARED_MEMORY --memorySize=2097152\n", program_name);
 47	 printf(" %s --continuous --interval=2 --output=capture --debug\n", program_name);
 48	}
