 49	 Ln.e("[" + TAG + "] 通信配置验证失败，退出程序");
 50	 System.exit(1);
 51	 }
 52	 // 准备主循环器
 53	 Ln.d("[" + TAG + "] 准备主事件循环器");
 54	 Looper.prepareMainLooper();
 55	 initializeServer();
 56	 // 创建并启动屏幕截图服务
 57	 Ln.d("[" + TAG + "] 创建屏幕捕获服务");
 58	 screenCaptureService = new ScreenCaptureService(CONFIG);
 59	 screenCaptureService.start();
 60	 // 运行主循环
 61	 Ln.i("[" + TAG + "] 进入主事件循环");
 62	 Looper.loop();
 63	 } catch (Exception e) {
 64	 Ln.e("[" + TAG + "] 启动过程中发生致命错误", e);
 65	 cleanup();
