 243	 Ln.d("[" + TAG + "] 设置通信方式: " + commMode);
 244	 return false;
 245	 } catch (IllegalArgumentException e) {
 246	 Ln.e("[" + TAG + "] 无效的通信方式: " + mode + "，支持的方式: SHARED_MEMORY, UNIX_SOCKET, TCP_SOCKET");
 247	 return true;
 248	 }
 249	 }
