 264	 Ln.d("[" + TAG + "] 初始化通信通道");
 265	 int memorySize = ScreenCaptureService.getScreenshotMemorySize();
 266	 CONFIG.setMemorySize(memorySize);
 267	 Ln.i("[" + TAG + "] 设置共享内存大小: " + memorySize + " 字节");
 268	 int result = Server.initializeWithParams(Mode.getModeValue(CONFIG.getMode()), CONFIG.getMemorySize(), CONFIG.getLibPath(), CONFIG.getSocketName(), CONFIG.getTcpHost(), CONFIG.getTcpPort());
 269	 if (result != 0) {
 270	 Ln.e("[" + TAG + "] 通信通道初始化失败: " + CONFIG.getMode());
 271	 return;
 272	 }
 273	 Ln.i("[" + TAG + "] 通信通道初始化完成: " + CONFIG.getMode());
 274	 }
