- **k-server.dex**: Android DEX服务器程序 (`server-k/build/k-server-output/k-server.dex`)
- **libserver-k.so**: 原生库文件 (`server-k/build/k-server-output/lib/arm64-v8a/libserver-k.so`)

## 实现方案

我建议在main.c中添加自动启动服务器的功能。以下是具体的实现方案：

### 1. 添加新的命令行参数

<augment_code_snippet path="server-k/src/main/cpp/client/main.c" mode="EXCERPT">
```c
// 打印使用帮助
void print_usage(const char* program_name) {
 printf("用法: %s [选项]\n", program_name);
 printf("\n选项:\n");
 printf(" --mode=MODE 通信模式 (SHARED_MEMORY|UNIX_SOCKET|TCP_SOCKET，默认: TCP_SOCKET)\n");
 printf(" --tcpHost=HOST TCP主机地址 (默认: 127.0.0.1)\n");
 printf(" --tcpPort=PORT TCP端口 (默认: 7777)\n");
 printf(" --socketName=NAME Unix套接字名称 (默认: server-k)\n");
 printf(" --memorySize=SIZE 共享内存大小 (默认: 1048576)\n");
 printf(" --continuous 连续截图模式\n");
 printf(" --interval=SECONDS 截图间隔秒数 (默认: 1)\n");
 printf(" --output=FILE 输出文件前缀 (默认: screenshot)\n");
 printf(" --auto-start-server 自动启动服务器（如果未运行）\n"); // 新增
 printf(" --debug 调试模式\n");
 printf(" --help 显示此帮助信息\n");
 printf(" --version 显示版本信息\n");
```
</augment_code_snippet>

### 2. 需要添加的辅助函数

```c
#include <sys/stat.h>
#include <unistd.h>

// 检查文件是否存在
int check_file_exists(const char* filepath) {
 return access(filepath, F_OK) == 0;
}

// 检查服务器是否运行（通过尝试快速连接）
int check_server_running(client_mode_t mode, const char* tcp_host, int tcp_port, const char* socket_name) {
 // 初始化客户端（使用较短超时）
 if (client_initialize_with_params(mode, 1024*1024, socket_name, tcp_host, tcp_port) != 0) {
 return -1;
 }

 // 尝试快速连接
 int result = client_connect();
 client_disconnect(); // 立即断开

 return result;
}

// 启动k-server
int start_k_server(client_mode_t mode, const char* tcp_host, int tcp_port, const char* socket_name, int debug_mode) {
 char cwd[1024];
 if (getcwd(cwd, sizeof(cwd)) == NULL) {
 printf("❌ 无法获取当前目录\n");
 return -1;
 }

 // 检查k-server.dex是否存在
 char dex_path[1024];
 snprintf(dex_path, sizeof(dex_path), "%s/k-server.dex", cwd);
 if (!check_file_exists(dex_path)) {
 printf("❌ 未找到k-server.dex文件: %s\n", dex_path);
 return -1;
 }

 // 检查libserver-k.so是否存在
 char lib_path[1024];
 snprintf(lib_path, sizeof(lib_path), "%s/lib/arm64-v8a", cwd);
 char lib_file[1024];
 snprintf(lib_file, sizeof(lib_file), "%s/libserver-k.so", lib_path);
 if (!check_file_exists(lib_file)) {
 printf("❌ 未找到libserver-k.so文件: %s\n", lib_file);
 return -1;
 }

 // 构造app_process命令
 char command[2048];
 const char* mode_str = (mode == CLIENT_MODE_TCP_SOCKET) ? "TCP_SOCKET" : 
 (mode == CLIENT_MODE_UNIX_SOCKET) ? "UNIX_SOCKET" : "SHARED_MEMORY";

 snprintf(command, sizeof(command), 
 "CLASSPATH=%s app_process /system/bin com.github.kirer.server.Launcher "
 "--mode=%s --libPath=%s --tcpHost=%s --tcpPort=%d %s > %s/k-server.log 2>&1 &",
 dex_path, mode_str, lib_path, tcp_host, tcp_port, 
 debug_mode ? "--debug" : "", cwd);

 if (debug_mode) {
 printf("[DEBUG] 执行命令: %s\n", command);
 }

 // 执行命令
 int result = system(command);
 if (result == 0) {
 printf("✅ 服务器启动命令执行成功\n");
 } else {
 printf("❌ 服务器启动命令执行失败，返回码: %d\n", result);
 }

 return result;
}
```

### 3. 修改主函数逻辑

在连接服务器之前添加自动启动检查：

```c
// 在main函数中，连接服务器之前添加：
if (auto_start_server) {
 if (debug_mode) {
 printf("[DEBUG] 检查服务器是否运行...\n");
 }

 // 尝试连接服务器检查是否已经运行
 if (check_server_running(mode, tcp_host, tcp_port, socket_name) != 0) {
 if (debug_mode) {
 printf("[DEBUG] 服务器未运行，尝试自动启动...\n");
 }

 // 启动服务器
 if (start_k_server(mode, tcp_host, tcp_port, socket_name, debug_mode) == 0) {
 printf("⏳ 等待服务器启动...\n");
 sleep(5); // 等待服务器启动

 // 再次检查服务器是否启动成功
 int retry_count = 0;
 while (retry_count < 10 && check_server_running(mode, tcp_host, tcp_port, socket_name) != 0) {
 sleep(1);
 retry_count++;
 if (debug_mode) {
 printf("[DEBUG] 等待服务器启动... (%d/10)\n", retry_count);
 }
 }

 if (retry_count >= 10) {
 printf("❌ 服务器启动超时\n");
 return 1;
 }
 } else {
 printf("❌ 服务器启动失败\n");
 return 1;
 }
 } else {
 if (debug_mode) {
 printf("[DEBUG] 服务器已经在运行\n");
 }
 }
}
```

## 使用方式

修改后，你可以这样使用：

```bash
# 将文件部署到同一目录
adb push k-client /data/local/tmp/
adb push k-server.dex /data/local/tmp/
adb push lib/ /data/local/tmp/

# 自动启动服务器并连接
adb shell 'cd /data/local/tmp && chmod +x k-client && ./k-client --auto-start-server --mode=TCP_SOCKET --tcpHost=127.0.0.1 --tcpPort=7777 --debug'
```

## 优势

1. **便利性**: 一个命令即可启动服务器和客户端
2. **智能检测**: 自动检查服务器是否已运行，避免重复启动
3. **向后兼容**: 不影响原有的客户端功能
4. **灵活性**: 可以选择是否启用自动启动功能

这样的实现既保持了原有功能，又增加了便利的自动启动服务器功能，完全满足你在同一目录下使用app_process启动k-server.dex的需求。"},{"id":2,"type":2,"content":"基于对项目代码的分析，我可以回答你的问题：**是的，main.c完全可以使用app_process启动k-server.dex**。

