IB_PATH\" ]; then\n echo \"\u274c \u670d\u52a1\u5668\u5e93\u6587\u4ef6\u4e0d\u5b58\u5728: $SERVER_LIB_PATH\"\n exit 1\nfi\n\necho \"\u2705 \u6240\u6709\u6587\u4ef6\u90fd\u5b58\u5728\"\necho\n\necho \"4. \u521b\u5efa\u6d4b\u8bd5\u76ee\u5f55...\"\nTEST_DIR=\"/tmp/k-server-test\"\nrm -rf \"$TEST_DIR\"\nmkdir -p \"$TEST_DIR/lib/arm64-v8a\"\n\necho \"5. \u590d\u5236\u6587\u4ef6\u5230\u6d4b\u8bd5\u76ee\u5f55...\"\ncp \"$CLIENT_PATH\" \"$TEST_DIR/\"\ncp \"$SERVER_DEX_PATH\" \"$TEST_DIR/\"\ncp \"$SERVER_LIB_PATH\" \"$TEST_DIR/lib/arm64-v8a/\"\n\necho \"\u2705 \u6587\u4ef6\u590d\u5236\u5b8c\u6210\"\necho\n\necho \"6. \u663e\u793a\u4f7f\u7528\u8bf4\u660e...\"\necho \"\u6d4b\u8bd5\u76ee\u5f55: $TEST_DIR\"\necho\necho \"\u5728Android\u8bbe\u5907\u4e0a\u6d4b\u8bd5\uff1a\"\necho \"adb push $TEST_DIR/* /data/local/tmp/\"\necho \"adb shell 'cd /data/local/tmp && chmod +x k-client && ./k-client --help'\"\necho\necho \"\u81ea\u52a8\u542f\u52a8\u670d\u52a1\u5668\u5e76\u8fde\u63a5\uff1a\"\necho \"adb shell 'cd /data/local/tmp && ./k-client --auto-start-server --mode=TCP_SOCKET --tcpHost=127.0.0.1 --tcpPort=7777 --debug'\"\necho\necho \"\u53ea\u8fde\u63a5\u670d\u52a1\u5668\uff08\u4e0d\u81ea\u52a8\u542f\u52a8\uff09\uff1a\"\necho \"adb shell 'cd /data/local/tmp && ./k-client --mode=TCP_SOCKET --tcpHost=127.0.0.1 --tcpPort=7777 --debug'\"\n\necho\necho \"=== \u6d4b\u8bd5\u51c6\u5907\u5b8c\u6210 ===\""}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"现在让我创建一个简单的测试脚本来验证修改是否正确：
