6210\u540e\uff0c\u7ee7\u7eed\u6b63\u5e38\u7684\u5ba2\u6237\u7aef\u8fde\u63a5\u6d41\u7a0b\n\n## \u4f7f\u7528\u65b9\u6cd5\n\n### 1. \u6784\u5efa\u7a0b\u5e8f\n```bash\n# \u6784\u5efa\u5ba2\u6237\u7aef\n./gradlew buildClient\n\n# \u6784\u5efa\u670d\u52a1\u5668\n./gradlew buildServer\n```\n\n### 2. \u90e8\u7f72\u5230\u8bbe\u5907\n```bash\n# \u521b\u5efa\u76ee\u5f55\u7ed3\u6784\nadb shell mkdir -p /data/local/tmp/lib/arm64-v8a\n\n# \u63a8\u9001\u6587\u4ef6\nadb push server-k/build/k-client-output/k-client /data/local/tmp/\nadb push server-k/build/k-server-output/k-server.dex /data/local/tmp/\nadb push server-k/build/k-server-output/lib/arm64-v8a/libserver-k.so /data/local/tmp/lib/arm64-v8a/\n\n# \u8bbe\u7f6e\u6267\u884c\u6743\u9650\nadb shell chmod +x /data/local/tmp/k-client\n```\n\n### 3. \u8fd0\u884c\n\n#### \u81ea\u52a8\u542f\u52a8\u670d\u52a1\u5668\u6a21\u5f0f\n```bash\nadb shell 'cd /data/local/tmp && ./k-client --auto-start-server --mode=TCP_SOCKET --tcpHost=127.0.0.1 --tcpPort=7777 --debug'\n```\n\n#### \u4f20\u7edf\u6a21\u5f0f\uff08\u9700\u8981\u624b\u52a8\u542f\u52a8\u670d\u52a1\u5668\uff09\n```bash\n# \u624b\u52a8\u542f\u52a8\u670d\u52a1\u5668\nadb shell 'cd /data/local/tmp && CLASSPATH=k-server.dex app_process /system/bin com.github.kirer.server.Launcher --mode=TCP_SOCKET --libPath=lib/arm64-v8a --tcpHost=127.0.0.1 --tcpPort=7777 --debug > k-server.log 2>&1 &'\n\n# \u8fd0\u884c\u5ba2\u6237\u7aef\nadb shell 'cd /data/local/tmp && ./k-client --mode=TCP_SOCKET --tcpHost=127.0.0.1 --tcpPort=7777 --debug'\n```\n\n## \u547d\u4ee4\u884c\u53c2\u6570\n\n### \u65b0\u589e\u53c2\u6570\n- `--auto-start-server`: \u81ea\u52a8\u542f\u52a8\u670d\u52a1\u5668\uff08\u5982\u679c\u672a\u8fd0\u884c\uff09\n\n### \u5b8c\u6574\u53c2\u6570\u5217\u8868\n```\n\u7528\u6cd5: k-client [\u9009\u9879]\n\n\u9009\u9879:\n --mode=MODE \u901a\u4fe1\u6a21\u5f0f (SHARED_MEMORY|UNIX_SOCKET|TCP_SOCKET\uff0c\u9ed8\u8ba4: TCP_SOCKET)\n --tcpHost=HOST TCP\u4e3b\u673a\u5730\u5740 (\u9ed8\u8ba4: 127.0.0.1)\n --tcpPort=PORT TCP\u7aef\u53e3 (\u9ed8\u8ba4: 7777)\n --socketName=NAME Unix\u5957\u63a5\u5b57\u540d\u79f0 (\u9ed8\u8ba4: server-k)\n --memorySize=SIZE \u5171\u4eab\u5185\u5b58\u5927\u5c0f (\u9ed8\u8ba4: 1048576)\n --continuous \u8fde\u7eed\u622a\u56fe\u6a21\u5f0f\n --interval=SECONDS \u622a\u56fe\u95f4\u9694\u79d2\u6570 (\u9ed8\u8ba4: 1)\n --output=FILE \u8f93\u51fa\u6587\u4ef6\u524d\u7f00 (\u9ed8\u8ba4: screenshot)\n --auto-start-server \u81ea\u52a8\u542f\u52a8\u670d\u52a1\u5668\uff08\u5982\u679c\u672a\u8fd0\u884c\uff09\n --debug \u8c03\u8bd5\u6a21\u5f0f\n --help \u663e\u793a\u6b64\u5e2e\u52a9\u4fe1\u606f\n --version \u663e\u793a\u7248\u672c\u4fe1\u606f\n\n\u793a\u4f8b:\n k-client --mode=TCP_SOCKET --tcpHost=127.0.0.1 --tcpPort=7777 --debug\n k-client --mode=UNIX_SOCKET --socketName=my-server\n k-client --mode=SHARED_MEMORY --memorySize=2097152\n k-client --continuous --interval=2 --output=capture --debug\n k-client --auto-start-server --mode=TCP_SOCKET --tcpHost=127.0.0.1 --tcpPort=7777 --debug\n```\n\n## \u65e5\u5fd7\u8f93\u51fa\n\n\u542f\u7528\u81ea\u52a8\u542f\u52a8\u529f\u80fd\u540e\uff0c\u4f60\u4f1a\u770b\u5230\u7c7b\u4f3c\u4ee5\u4e0b\u7684\u8f93\u51fa\uff1a\n\n```\n=== Server-K \u5ba2\u6237\u7aef v1.0.0 ===\n\u901a\u4fe1\u6a21\u5f0f: TCP\u5957\u63a5\u5b57\n\u670d\u52a1\u5668\u5730\u5740: 127.0.0.1:7777\n\u8f93\u51fa\u524d\u7f00: screenshot\n\u8c03\u8bd5\u6a21\u5f0f: \u5f00\u542f\n\u81ea\u52a8\u542f\u52a8\u670d\u52a1\u5668: \u5f00\u542f\n================================\n\n[DEBUG] \u68c0\u67e5\u670d\u52a1\u5668\u662f\u5426\u8fd0\u884c...\n[DEBUG] \u670d\u52a1\u5668\u672a\u8fd0\u884c\uff0c\u5c1d\u8bd5\u81ea\u52a8\u542f\u52a8...\n\ud83d\ude80 \u542f\u52a8\u670d\u52a1\u5668...\n[DEBUG] \u6267\u884c\u547d\u4ee4: CLASSPATH=/data/local/tmp/k-server.dex app_process /system/bin com.github.kirer.server.Launcher --mode=TCP_SOCKET --libPath=/data/local/tmp/lib/arm64-v8a --tcpHost=127.0.0.1 --tcpPort=7777 --debug > /data/local/tmp/k-server.log 2>&1 &\n\u2705 \u670d\u