 if (mode == CLIENT_MODE_TCP_SOCKET) {\n int sockfd = socket(AF_INET, SOCK_STREAM, 0);\n if (sockfd < 0) {\n return -1;\n }\n \n struct sockaddr_in server_addr;\n memset(&server_addr, 0, sizeof(server_addr));\n server_addr.sin_family = AF_INET;\n server_addr.sin_port = htons(tcp_port);\n \n if (inet_pton(AF_INET, tcp_host, &server_addr.sin_addr) <= 0) {\n close(sockfd);\n return -1;\n }\n \n // \u8bbe\u7f6e\u975e\u963b\u585e\u6a21\u5f0f\u8fdb\u884c\u5feb\u901f\u8fde\u63a5\u6d4b\u8bd5\n int flags = fcntl(sockfd, F_GETFL, 0);\n fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);\n \n int result = connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr));\n if (result == 0 || errno == EINPROGRESS) {\n // \u8fde\u63a5\u6210\u529f\u6216\u6b63\u5728\u8fdb\u884c\u4e2d\n close(sockfd);\n if (debug_mode) {\n printf(\"[DEBUG] \u670d\u52a1\u5668\u6b63\u5728\u8fd0\u884c\\n\");\n }\n return 0;\n }\n \n close(sockfd);\n } else {\n // \u5bf9\u4e8e\u5176\u4ed6\u6a21\u5f0f\uff0c\u4f7f\u7528\u7b80\u5355\u7684\u6587\u4ef6/socket\u5b58\u5728\u6027\u68c0\u67e5\n if (mode == CLIENT_MODE_UNIX_SOCKET) {\n char socket_path[256];\n snprintf(socket_path, sizeof(socket_path), \"/tmp/%s\", socket_name);\n if (access(socket_path, F_OK) == 0) {\n if (debug_mode) {\n printf(\"[DEBUG] Unix socket\u6587\u4ef6\u5b58\u5728\uff0c\u5047\u8bbe\u670d\u52a1\u5668\u6b63\u5728\u8fd0\u884c\\n\");\n }\n return 0;\n }\n }\n }\n \n if (debug_mode) {\n printf(\"[DEBUG] \u670d\u52a1\u5668\u672a\u8fd0\u884c\\n\");\n }\n return -1;\n}", "old_str_start_line_number": 78, "old_str_end_line_number": 103}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"我看到问题了！从日志可以看出有两个主要问题：

