K);\n \n int result = connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr));\n if (result == 0 || errno == EINPROGRESS) {\n // \u8fde\u63a5\u6210\u529f\u6216\u6b63\u5728\u8fdb\u884c\u4e2d\n close(sockfd);\n if (debug_mode) {\n printf(\"[DEBUG] \u670d\u52a1\u5668\u6b63\u5728\u8fd0\u884c\\n\");\n }\n return 0;\n }\n \n close(sockfd);\n } else {\n // \u5bf9\u4e8e\u5176\u4ed6\u6a21\u5f0f\uff0c\u4f7f\u7528\u7b80\u5355\u7684\u6587\u4ef6/socket\u5b58\u5728\u6027\u68c0\u67e5\n if (mode == CLIENT_MODE_UNIX_SOCKET) {\n char socket_path[256];\n snprintf(socket_path, sizeof(socket_path), \"/tmp/%s\", socket_name);\n if (access(socket_path, F_OK) == 0) {\n if (debug_mode) {\n printf(\"[DEBUG] Unix socket\u6587\u4ef6\u5b58\u5728\uff0c\u5047\u8bbe\u670d\u52a1\u5668\u6b63\u5728\u8fd0\u884c\\n\");\n }\n return 0;\n }\n }\n }\n \n if (debug_mode) {\n printf(\"[DEBUG] \u670d\u52a1\u5668\u672a\u8fd0\u884c\\n\");\n }\n return -1;\n}", "new_str": "// \u505c\u6b62\u5df2\u8fd0\u884c\u7684\u670d\u52a1\u5668\nint stop_existing_server(void) {\n if (debug_mode) {\n printf(\"[DEBUG] \u505c\u6b62\u5df2\u8fd0\u884c\u7684\u670d\u52a1\u5668...\\n\");\n }\n \n char command[256];\n snprintf(command, sizeof(command), \"pkill -f 'com.github.kirer.server.Launcher'\");\n \n printf(\"\ud83d\uded1 \u505c\u6b62\u5df2\u8fd0\u884c\u7684\u670d\u52a1\u5668...\\n\");\n printf(\"\ud83d\udccb \u505c\u6b62\u547d\u4ee4: %s\\n\", command);\n \n int result = system(command);\n if (result == 0) {\n printf(\"\u2705 \u670d\u52a1\u5668\u505c\u6b62\u547d\u4ee4\u6267\u884c\u6210\u529f\\n\");\n sleep(2); // \u7b49\u5f85\u8fdb\u7a0b\u5b8c\u5168\u505c\u6b62\n } else {\n if (debug_mode) {\n printf(\"[DEBUG] \u505c\u6b62\u547d\u4ee4\u6267\u884c\u5b8c\u6210 (\u53ef\u80fd\u6ca1\u6709\u8fd0\u884c\u7684\u670d\u52a1\u5668)\\n\");\n }\n }\n \n return 0;\n}", "old_str_start_line_number": 82, "old_str_end_line_number": 134}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"明白了！你想要简化逻辑，不需要检查服务器是否运行，而是每