705 \u68c0\u6d4b\u5230\u670d\u52a1\u5668\u6b63\u5728\u8fd0\u884c\\n\");\n }\n }", "new_str": " // \u81ea\u52a8\u542f\u52a8\u670d\u52a1\u5668\n if (auto_start_server) {\n if (debug_mode) {\n printf(\"[DEBUG] \u542f\u7528\u81ea\u52a8\u542f\u52a8\u670d\u52a1\u5668\u529f\u80fd\\n\");\n }\n \n // \u5148\u505c\u6b62\u5df2\u8fd0\u884c\u7684\u670d\u52a1\u5668\n stop_existing_server();\n \n // \u542f\u52a8\u670d\u52a1\u5668\n if (start_k_server(mode, tcp_host, tcp_port, socket_name, debug_mode) == 0) {\n printf(\"\u23f3 \u7b49\u5f85\u670d\u52a1\u5668\u542f\u52a8...\\n\");\n sleep(5); // \u7b49\u5f85\u670d\u52a1\u5668\u542f\u52a8\n printf(\"\u2705 \u670d\u52a1\u5668\u542f\u52a8\u5b8c\u6210\uff01\\n\");\n } else {\n printf(\"\u274c \u670d\u52a1\u5668\u542f\u52a8\u5931\u8d25\\n\");\n return 1;\n }\n }", "old_str_start_line_number": 340, "old_str_end_line_number": 378}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"type":0,"content":"现在修改自动启动服务器的逻辑，移除检查服务器运行状态的部分，直接停止并启动：
