def generateClassesHeader(String dexFilePath, String outputPath) {
 def dexFile = new File(dexFilePath)
 if (!dexFile.exists()) {
 println "❌ DEX文件不存在: ${dexFilePath}"
 return
 }

 def outputFile = new File(outputPath)
 def dexBytes = dexFile.bytes

 outputFile.withWriter { writer ->
 writer.println "unsigned char classes[] = {"

 // 每行12个字节，与原文件格式保持一致
 def bytesPerLine = 12
 for (int i = 0; i < dexBytes.length; i += bytesPerLine) {
 def line = []
 for (int j = 0; j < bytesPerLine && (i + j) < dexBytes.length; j++) {
 def byteValue = dexBytes[i + j] & 0xFF
 line.add(String.format("0x%02x", byteValue))
 }

 def lineStr = " " + line.join(", ")
 if (i + bytesPerLine < dexBytes.length) {
 lineStr += ","
 }
 writer.println lineStr
 }

 writer.println "};"
 writer.println "unsigned int classes_len = ${dexBytes.length};"
 }

 println "✅ 成功生成 classes.h"
 println " DEX文件大小: ${dexBytes.length} 字节"
 println " 输出路径: ${outputPath}"
