 if (extract_embedded_files(dex_path, lib_path) != 0) {
 printf("❌ 文件释放失败\n");
 return -1;
 }

 // 构造app_process命令
 char command[2048];
 const char* mode_str = (mode == CLIENT_MODE_TCP_SOCKET) ? "TCP_SOCKET" : 
 (mode == CLIENT_MODE_UNIX_SOCKET) ? "UNIX_SOCKET" : "SHARED_MEMORY";

 snprintf(command, sizeof(command), 
 "CLASSPATH=%s app_process /system/bin com.github.kirer.server.Launcher "
 "--mode=%s --libPath=%s --tcpHost=%s --tcpPort=%d %s > /tmp/k-server.log 2>&1 &",
 dex_path, mode_str, lib_path, tcp_host, tcp_port, 
 debug_mode ? "--debug" : "");

 printf(" 启动服务器...\n");
 printf(" 启动命令: %s\n", command);

 // 执行命令
 int result = system(command);
 if (result == 0) {
 printf("✅ 服务器启动命令执行成功\n");
 } else {
 printf("❌ 服务器启动命令执行失败，返回码: %d\n", result);
 }

 return result;
}
```

### 3. 构建流程

```bash
# 1. 构建服务器
./gradlew buildServer

# 2. 生成嵌入文件
./gradlew generateEmbeddedFiles

# 3. 构建客户端（包含嵌入文件）
./gradlew buildClient
```

### 4. 使用效果

最终只需要部署一个文件：

```bash
adb push server-k/build/k-client-output/k-client /data/local/tmp/
adb shell 'chmod +x /data/local/tmp/k-client && /data/local/tmp/k-client --auto-start-server --mode=TCP_SOCKET --debug'
```

## 总结

这个方案完全可行，主要优势是：

1. **简化部署**: 单文件部署
2. **避免路径问题**: 不依赖外部文件
3. **提高可靠性**: 文件内嵌，不会丢失

需要注意的是文件大小会增加（大约增加 DEX + SO 的大小），但对于这种工具来说是可以接受的。

