 114	int extract_embedded_files(char* dex_path, char* lib_path) {
 115	 // 创建临时目录
 116	 char temp_dir[] = "/data/local/tmp/k-server-XXXXXX";
 117	 if (mkdtemp(temp_dir) == NULL) {
 118	 printf("❌ 无法创建临时目录\n");
 119	 return -1;
 120	 }
 121	
 122	 if (g_debug_mode) {
 123	 printf("[DEBUG] 临时目录: %s\n", temp_dir);
 124	 }
 125	
 126	 // 创建lib目录
 127	 char lib_dir[1024];
 128	 snprintf(lib_dir, sizeof(lib_dir), "%s/lib/arm64-v8a", temp_dir);
 129	 char mkdir_cmd[1024];
 130	 snprintf(mkdir_cmd, sizeof(mkdir_cmd), "mkdir -p %s", lib_dir);
 131	 system(mkdir_cmd);
 132	
 133	 // 写入k-server.dex
 134	 snprintf(dex_path, 1024, "%s/k-server.dex", temp_dir);
 135	 if (write_temp_file(dex_path, k_server_dex_data, k_server_dex_len) != 0) {
 136	 return -1;
 137	 }
 138	
 139	 // 写入libserver-k.so
 140	 snprintf(lib_path, 1024, "%s/lib/arm64-v8a", temp_dir);
 141	 char so_file[1024];
 142	 snprintf(so_file, sizeof(so_file), "%s/libserver-k.so", lib_path);
 143	 if (write_temp_file(so_file, libserver_k_so_data, libserver_k_so_len) != 0) {
 144	 return -1;
 145	 }
 146	
 147	 // 设置执行权限
 148	 chmod(so_file, 0755);
 149	
 150	 printf("✅ 文件释放完成\n");
 151	 printf(" DEX: %s (%u 字节)\n", dex_path, k_server_dex_len);
 152	 printf(" SO: %s (%u 字节)\n", so_file, libserver_k_so_len);
 153	
 154	 return 0;
 155	}
