 99	// Unix套接字服务器停止
 100	int unix_server_stop(void) {
 101	 LOG_INFO(UNIX_SERVER_LOG_TAG, "停止Unix套接字服务器");
 102	
 103	 // 关闭所有客户端连接
 104	 for (int i = 0; i < MAX_CLIENTS; i++) {
 105	 if (g_server_ctx.server_data.unix_socket.client_fds[i] >= 0) {
 106	 unix_server_close_client(i);
 107	 }
 108	 }
 109	
 110	 // 关闭服务器socket
 111	 if (g_server_ctx.server_data.unix_socket.server_fd >= 0) {
 112	 close(g_server_ctx.server_data.unix_socket.server_fd);
 113	 g_server_ctx.server_data.unix_socket.server_fd = -1;
 114	 }
 115	
 116	 // 删除socket文件
 117	 char socket_path[256];
 118	 snprintf(socket_path, sizeof(socket_path), "%s%s",
 119	 UNIX_SOCKET_PATH_PREFIX, g_server_ctx.config.socket_name);
 120	 unlink(socket_path);
 121	
 122	 g_server_ctx.server_data.unix_socket.client_count = 0;
 123	
 124	 LOG_INFO(UNIX_SERVER_LOG_TAG, "Unix套接字服务器已停止");
 125	 return 0;
 126	}
