 10	// Unix套接字客户端操作函数表
 11	static const client_ops_t unix_client_ops = {
 12	 .connect = unix_client_connect,
 13	 .disconnect = unix_client_disconnect,
 14	 .take_screenshot = unix_client_take_screenshot,
 15	 .cleanup = unix_client_cleanup
