 383	 backgroundThread.join(1000); // 等待最多1秒
 384	 Ln.d("[" + TAG + "] 后台线程已停止");
 385	 } catch (InterruptedException e) {
 386	 Ln.w("[" + TAG + "] 等待后台线程停止时被中断");
 387	 }
 388	 backgroundThread = null;
 389	 backgroundHandler = null;
 390	 }
