 394	 Server.stop();
 395	 Ln.d("[" + TAG + "] 通信通道已停止");
 396	 } catch (Exception e) {
 397	 Ln.w("[" + TAG + "] 停止通信通道时出错", e);
 398	 }
 399	 isRunning.set(false);
 400	 Ln.i("[" + TAG + "] 屏幕捕获服务已停止");
 401	 }
