 403	 /**
 404	 * 处理ImageReader
 405	 */
 406	 private void processImage() {
 407	 long startTime = System.currentTimeMillis();
 408	 synchronized (imageLock) {
 409	 Image image = null;
 410	 try {
 411	 // 获取最新图像
 412	 image = imageReader.acquireLatestImage();
 413	 if (image == null) {
 414	 return;
 415	 }
 416	 // 处理图像数据
 417	 processImageData(image);
 418	 lastFrameTime = System.currentTimeMillis();
 419	 long processingTime = lastFrameTime - startTime;
 420	 Ln.d("[帧处理] 耗时 " + processingTime + "ms");
 421	 } catch (Exception e) {
 422	 Ln.w("[帧处理] 回调中处理图像时出错", e);
 423	 } finally {
 424	 if (image != null) {
 425	 try {
 426	 image.close();
 427	 } catch (Exception e) {
 428	 Ln.w("[帧处理] 关闭图像时出错", e);
 429	 }
 430	 }
 431	 }
 432	 }
 433	 }
