 36	 }
 37	 g_server_ctx.server_data.unix_socket.client_count = 0;
 38	 g_server_ctx.server_data.unix_socket.server_fd = -1;
 39	
 40	 LOG_INFO(UNIX_SERVER_LOG_TAG, "Unix套接字服务器初始化成功，套接字名称: %s",
 41	 config->socket_name);
 42	
 43	 return 0;
 44	}
 45	
 46	// Unix套接字服务器启动
 47	int unix_server_start(void) {
 48	 LOG_INFO(UNIX_SERVER_LOG_TAG, "启动Unix套接字服务器");
 49	
 50	 // 创建socket
 51	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "创建Unix套接字...");
 52	 int server_fd = socket(AF_UNIX, SOCK_STREAM, 0);
 53	 if (server_fd < 0) {
 54	 LOG_ERROR(UNIX_SERVER_LOG_TAG, "创建套接字失败: %s", strerror(errno));
 55	 return -1;
 56	 }
 57	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "Unix套接字创建成功，fd: %d", server_fd);
 58	
 59	 // 设置socket为非阻塞模式
 60	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "设置套接字为非阻塞模式...");
 61	 int flags = fcntl(server_fd, F_GETFL, 0);
 62	 if (flags < 0 || fcntl(server_fd, F_SETFL, flags | O_NONBLOCK) < 0) {
 63	 LOG_WARN(UNIX_SERVER_LOG_TAG, "设置套接字非阻塞模式失败: %s", strerror(errno));
 64	 } else {
 65	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "套接字非阻塞模式设置成功");
 66	 }
 67	
 68	 // 使用Abstract Unix Socket（不需要文件系统权限）
 69	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "使用Abstract Unix Socket: @%s", g_server_ctx.config.socket_name);
 70	
 71	 // 绑定socket
 72	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "绑定Abstract Unix套接字...");
 73	 struct sockaddr_un addr;
 74	 memset(&addr, 0, sizeof(addr));
 75	 addr.sun_family = AF_UNIX;
 76	
 77	 // Abstract socket: 第一个字符为'\0'，后面跟socket名称
 78	 addr.sun_path[0] = '\0';
 79	 strncpy(addr.sun_path + 1, g_server_ctx.config.socket_name, sizeof(addr.sun_path) - 2);
 80	
 81	 // Abstract socket的长度计算
 82	 int addr_len = sizeof(addr.sun_family) + 1 + strlen(g_server_ctx.config.socket_name);
 83	
 84	 if (bind(server_fd, (struct sockaddr*)&addr, addr_len) < 0) {
 85	 LOG_ERROR(UNIX_SERVER_LOG_TAG, "绑定Abstract套接字 @%s 失败: %s",
 86	 g_server_ctx.config.socket_name, strerror(errno));
 87	 close(server_fd);
 88	 return -1;
 89	 }
 90	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "Unix套接字绑定成功");
 91	
 92	 // 监听连接
 93	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "开始监听连接，最大客户端数: %d", MAX_CLIENTS);
 94	 if (listen(server_fd, MAX_CLIENTS) < 0) {
 95	 LOG_ERROR(UNIX_SERVER_LOG_TAG, "监听套接字失败: %s", strerror(errno));
 96	 close(server_fd);
 97	 // Abstract socket不需要unlink
 98	 return -1;
 99	 }
 100	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "Unix套接字监听成功");
 101	
 102	 // 保存服务器文件描述符
 103	 g_server_ctx.server_data.unix_socket.server_fd = server_fd;
 104	
 105	 LOG_INFO(UNIX_SERVER_LOG_TAG, "Abstract Unix套接字服务器启动成功，名称: @%s", g_server_ctx.config.socket_name);
 106	 return 0;
 107	}
 108	
 109	// Unix套接字服务器停止
 110	int unix_server_stop(void) {
 111	 LOG_INFO(UNIX_SERVER_LOG_TAG, "停止Unix套接字服务器");
 112	
 113	 // 关闭所有客户端连接
 114	 for (int i = 0; i < MAX_CLIENTS; i++) {
 115	 if (g_server_ctx.server_data.unix_socket.client_fds[i] >= 0) {
 116	 unix_server_close_client(i);
 117	 }
 118	 }
 119	
 120	 // 关闭服务器socket
 121	 if (g_server_ctx.server_data.unix_socket.server_fd >= 0) {
 122	 close(g_server_ctx.server_data.unix_socket.server_fd);
 123	 g_server_ctx.server_data.unix_socket.server_fd = -1;
 124	 }
 125	
 126	 // 删除socket文件
 127	 char socket_path[256];
 128	 snprintf(socket_path, sizeof(socket_path), "%s%s",
 129	 UNIX_SOCKET_PATH_PREFIX, g_server_ctx.config.socket_name);
 130	 unlink(socket_path);
 131	
 132	 g_server_ctx.server_data.unix_socket.client_count = 0;
 133	
 134	 LOG_INFO(UNIX_SERVER_LOG_TAG, "Unix套接字服务器已停止");
 135	 return 0;
 136	}
