 210	// 发送数据到所有客户端
 211	int unix_server_send_to_clients(const uint8_t* data, size_t size) {
 212	 if (g_server_ctx.server_data.unix_socket.client_count == 0) {
 213	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "没有客户端连接，跳过数据发送");
 214	 return 0;
 215	 }
 216	
 217	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "向 %d 个客户端发送数据，大小: %zu 字节",
 218	 g_server_ctx.server_data.unix_socket.client_count, size);
 219	
 220	 // 准备数据包（4字节长度头 + 数据）
 221	 uint32_t data_length = (uint32_t)size;
 222	 uint8_t header[4];
 223	 header[0] = (uint8_t)(data_length & 0xFF);
 224	 header[1] = (uint8_t)((data_length >> 8) & 0xFF);
 225	 header[2] = (uint8_t)((data_length >> 16) & 0xFF);
 226	 header[3] = (uint8_t)((data_length >> 24) & 0xFF);
 227	
 228	 int success_count = 0;
 229	
 230	 for (int i = 0; i < MAX_CLIENTS; i++) {
 231	 int client_fd = g_server_ctx.server_data.unix_socket.client_fds[i];
 232	 if (client_fd < 0) {
 233	 continue;
 234	 }
 235	
 236	 // 发送长度头
 237	 ssize_t sent = send(client_fd, header, 4, MSG_NOSIGNAL);
 238	 if (sent != 4) {
 239	 LOG_WARN(UNIX_SERVER_LOG_TAG, "向客户端 %d 发送数据头失败: %s",
 240	 client_fd, strerror(errno));
 241	 unix_server_close_client(i);
 242	 continue;
 243	 }
 244	
 245	 // 发送数据
 246	 sent = send(client_fd, data, size, MSG_NOSIGNAL);
 247	 if (sent != (ssize_t)size) {
 248	 LOG_WARN(UNIX_SERVER_LOG_TAG, "向客户端 %d 发送数据失败: %s",
 249	 client_fd, strerror(errno));
 250	 unix_server_close_client(i);
 251	 continue;
 252	 }
 253	
 254	 success_count++;
 255	 }
 256	
 257	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "成功向 %d 个客户端发送数据", success_count);
 258	 return success_count > 0 ? 0 : -1;
 259	}
