 78	 } else if (strcmp(mode_str, "TCP_SOCKET") == 0) {
 79	 return CLIENT_MODE_TCP_SOCKET;
 80	 } else {
 81	 return CLIENT_MODE_TCP_SOCKET; // 默认
 82	 }
 83	}
