 182	// 启动k-server
 183	int start_k_server(client_mode_t mode, const char* tcp_host, int tcp_port, const char* socket_name) {
 184	 char dex_path[1024];
 185	 char lib_path[1024];
 186	
 187	 printf(" 释放嵌入的服务器文件...\n");
 188	
 189	 // 释放嵌入的文件
 190	 if (extract_embedded_files(dex_path, lib_path) != 0) {
 191	 printf("❌ 文件释放失败\n");
 192	 return -1;
 193	 }
 194	
 195	 // 构造app_process命令
 196	 char command[2048];
 197	 const char* mode_str = (mode == CLIENT_MODE_TCP_SOCKET) ? "TCP_SOCKET" :
 198	 (mode == CLIENT_MODE_UNIX_SOCKET) ? "UNIX_SOCKET" : "SHARED_MEMORY";
 199	
 200	 // 根据不同模式构造不同的参数
 201	 switch (mode) {
 202	 case CLIENT_MODE_TCP_SOCKET:
 203	 snprintf(command, sizeof(command),
 204	 "CLASSPATH=%s app_process /system/bin com.github.kirer.server.Launcher "
 205	 "--mode=%s --libPath=%s --tcpHost=%s --tcpPort=%d %s > /data/local/tmp/k-server.log 2>&1 &",
 206	 dex_path, mode_str, lib_path, tcp_host, tcp_port,
 207	 g_debug_mode ? "--debug" : "");
 208	 break;
 209	
 210	 case CLIENT_MODE_UNIX_SOCKET:
 211	 snprintf(command, sizeof(command),
 212	 "CLASSPATH=%s app_process /system/bin com.github.kirer.server.Launcher "
 213	 "--mode=%s --libPath=%s --socketName=%s %s > /data/local/tmp/k-server.log 2>&1 &",
 214	 dex_path, mode_str, lib_path, socket_name,
 215	 g_debug_mode ? "--debug" : "");
 216	 break;
 217	
 218	 case CLIENT_MODE_SHARED_MEMORY:
 219	 snprintf(command, sizeof(command),
 220	 "CLASSPATH=%s app_process /system/bin com.github.kirer.server.Launcher "
 221	 "--mode=%s --libPath=%s %s > /data/local/tmp/k-server.log 2>&1 &",
 222	 dex_path, mode_str, lib_path,
 223	 g_debug_mode ? "--debug" : "");
 224	 break;
 225	
 226	 default:
 227	 printf("❌ 不支持的通信模式: %d\n", mode);
 228	 return -1;
 229	 }
 230	
 231	 printf(" 启动服务器...\n");
 232	 printf(" 启动命令: %s\n", command);
 233	
 234	 // 执行命令
 235	 int result = system(command);
 236	 if (result == 0) {
 237	 printf("✅ 服务器启动命令执行成功\n");
 238	 } else {
 239	 printf("❌ 服务器启动命令执行失败，返回码: %d\n", result);
 240	 }
 241	
 242	 return result;
 243	}
