 110	 response->data_size = 0;
 111	 
 112	 if (g_client_ctx.client_data.unix_socket.socket_fd < 0) {
 113	 strcpy(response->message, "套接字未连接");
 114	 response->processing_time = get_current_time_ms() - start_time;
 115	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "套接字未连接");
 116	 return response;
 117	 }
