 90	// 保存截图数据到文件
 91	int save_screenshot(const uint8_t* data, size_t size, const char* filename) {
 92	 if (size < 8) {
 93	 printf("错误: 数据格式错误，数据太小\n");
 94	 return -1;
 95	 }
 96	
 97	 // 首先尝试使用OpenCV保存
 98	 if (debug_mode) {
 99	 printf("[DEBUG] 尝试使用OpenCV保存截图...\n");
 100	 }
 101	
 102	 int opencv_result = opencv_save_screenshot(data, size, filename, debug_mode);
 103	 if (opencv_result == 0) {
 104	 if (debug_mode) {
 105	 printf("[DEBUG] ✅ OpenCV保存成功\n");
 106	 }
 107	 } else {
 108	 if (debug_mode) {
 109	 printf("[DEBUG] ❌ OpenCV保存失败\n");
 110	 }
 111	 }
 112	 return 0;
 113	}
