 69	/**
 70	 * 查找Android NDK路径
 71	 */
 72	fun findAndroidNdk(): String {
 73	 // 1. 检查环境变量
 74	 val ndkFromEnv = System.getenv("ANDROID_NDK") ?: System.getenv("ANDROID_NDK_ROOT")
 75	 if (ndkFromEnv != null && File(ndkFromEnv).exists()) {
 76	 return ndkFromEnv
 77	 }
 78	 // 2. 从Android SDK路径查找
 79	 val androidHome = System.getenv("ANDROID_HOME") ?: System.getenv("ANDROID_SDK_ROOT")
 80	 if (androidHome != null) {
 81	 val ndkDir = File(androidHome, "ndk")
 82	 if (ndkDir.exists()) {
 83	 // 查找最新版本的NDK
 84	 val ndkVersions = ndkDir.listFiles()?.filter {
 85	 it.isDirectory && it.name.matches(Regex("\\d+\\..*"))
 86	 }?.sortedByDescending { it.name }
 87	
 88	 if (ndkVersions?.isNotEmpty() == true) {
 89	 return ndkVersions.first().absolutePath
 90	 }
 91	 }
 92	 }
 93	 throw GradleException("未找到Android NDK。请设置环境变量 ANDROID_NDK 或 ANDROID_NDK_ROOT")
 94	}
