 96	/**
 97	 * 查找dx工具路径
 98	 */
 99	fun findDxTool(androidHome: String): String {
 100	 // 新版本的dx工具路径
 101	 val newDxPath = File(androidHome, "build-tools").listFiles()
 102	 ?.filter { it.isDirectory && it.name.matches(Regex("\\d+\\..*")) }
 103	 ?.maxByOrNull { it.name }
 104	 ?.let { File(it, "dx") }
 105	 if (newDxPath?.exists() == true) {
 106	 return newDxPath.absolutePath
 107	 }
 108	 // 旧版本的dx工具路径
 109	 val oldDxPath = File(androidHome, "platform-tools/dx")
 110	 if (oldDxPath.exists()) {
 111	 return oldDxPath.absolutePath
 112	 }
 113	 // 在build-tools中查找任何版本的dx
 114	 val buildToolsDir = File(androidHome, "build-tools")
 115	 if (buildToolsDir.exists()) {
 116	 buildToolsDir.listFiles()?.forEach { versionDir ->
 117	 if (versionDir.isDirectory) {
 118	 val dxFile = File(versionDir, "dx")
 119	 if (dxFile.exists()) {
 120	 return dxFile.absolutePath
 121	 }
 122	 }
 123	 }
 124	 }
 125	
 126	 throw GradleException("未找到dx工具，请检查Android SDK安装")
 127	}
