 129	/**
 130	 * 查找CMake工具路径
 131	 */
 132	fun findCMakePath(): String {
 133	 val osName = System.getProperty("os.name").lowercase()
 134	 val isWindows = osName.contains("windows")
 135	
 136	 // 根据操作系统确定可能的CMake路径
 137	 val possiblePaths = when {
 138	 isWindows -> listOfNotNull(
 139	 "cmake.exe", // PATH中的cmake
 140	 "C:\\Program Files\\CMake\\bin\\cmake.exe", // 默认安装路径
 141	 "C:\\Program Files (x86)\\CMake\\bin\\cmake.exe", // 32位安装路径
 142	 "C:\\Tools\\cmake\\bin\\cmake.exe", // Chocolatey安装路径
 143	 System.getenv("ProgramFiles")?.let { "$it\\CMake\\bin\\cmake.exe" }, // 动态Program Files路径
 144	 System.getenv("ProgramFiles(x86)")?.let { "$it\\CMake\\bin\\cmake.exe" } // 动态Program Files (x86)路径
 145	 )
 146	 else -> listOf(
 147	 "cmake", // PATH中的cmake
 148	 "/opt/homebrew/bin/cmake", // Homebrew on Apple Silicon
 149	 "/usr/local/bin/cmake", // Homebrew on Intel Mac / Linux
 150	 "/usr/bin/cmake", // System installation
 151	 "/snap/bin/cmake" // Snap package on Linux
 152	 )
 153	 }
 154	
 155	 println("正在查找CMake，操作系统: $osName")
 156	 println("候选路径: ${possiblePaths.joinToString(", ")}")
 157	
 158	 for (path in possiblePaths) {
 159	 try {
 160	 println("尝试路径: $path")
 161	 val process = ProcessBuilder(path, "--version")
 162	 .redirectErrorStream(true)
 163	 .start()
 164	 val result = process.waitFor()
 165	 if (result == 0) {
 166	 val output = process.inputStream.bufferedReader().readText()
 167	 println("✅ 找到CMake: $path")
 168	 println("版本信息: ${output.lines().firstOrNull() ?: "未知版本"}")
 169	 return path
 170	 } else {
 171	 println("❌ 路径无效: $path (退出码: $result)")
 172	 }
 173	 } catch (e: Exception) {
 174	 println("❌ 路径测试失败: $path (${e.message})")
 175	 }
 176	 }
 177	
 178	 val installInstructions = when {
 179	 isWindows -> "请安装CMake: https://cmake.org/download/ 或使用 choco install cmake"
 180	 osName.contains("mac") -> "请安装CMake: brew install cmake"
 181	 else -> "请安装CMake: sudo apt-get install cmake 或 sudo yum install cmake"
 182	 }
 183	
 184	 throw GradleException("未找到CMake工具，$installInstructions")
 185	}
