 10	/**
 11	 * Log both to Android logger (so that logs are visible in "adb logcat") and standard output/error (so that they are visible in the terminal
 12	 * directly).
 13	 */
 14	public final class Ln {
 15	
 16	 private static final String TAG = "k-scrcpy";
 17	 private static final String PREFIX = "[k-server] ";
 18	
 19	 private static final PrintStream CONSOLE_OUT = new PrintStream(new FileOutputStream(FileDescriptor.out));
 20	 private static final PrintStream CONSOLE_ERR = new PrintStream(new FileOutputStream(FileDescriptor.err));
 21	
 22	 public enum Level {
 23	 VERBOSE, DEBUG, INFO, WARN, ERROR
 24	 }
 25	
 26	 private static Level threshold = Level.INFO;
 27	
 28	 private Ln() {
 29	 // not instantiable
 30	 }
 31	
 32	 public static void disableSystemStreams() {
 33	 PrintStream nullStream = new PrintStream(new NullOutputStream());
 34	 System.setOut(nullStream);
 35	 System.setErr(nullStream);
 36	 }
 37	
 38	 /**
 39	 * Initialize the log level.
 40	 * <p>
 41	 * Must be called before starting any new thread.
 42	 *
 43	 * @param level the log level
 44	 */
 45	 public static void initLogLevel(Level level) {
 46	 threshold = level;
 47	 }
 48	
 49	 public static boolean isEnabled(Level level) {
 50	 return level.ordinal() >= threshold.ordinal();
 51	 }
 52	
 53	 public static void v(String message) {
 54	 if (isEnabled(Level.VERBOSE)) {
 55	 Log.v(TAG, message);
 56	 CONSOLE_OUT.print(PREFIX + "VERBOSE: " + message + '\n');
 57	 }
 58	 }
 59	
 60	 public static void d(String message) {
 61	 if (isEnabled(Level.DEBUG)) {
 62	 Log.d(TAG, message);
 63	 CONSOLE_OUT.print(PREFIX + "DEBUG: " + message + '\n');
 64	 }
 65	 }
