 8	/**
 9	 * 主入口类 - K Server 屏幕截图服务启动器
 10	 * <p>
 11	 * 功能：
 12	 * 1. 解析命令行参数
 13	 * 2. 初始化屏幕截图服务
 14	 * 3. 启动持续的屏幕捕获循环
 15	 * 4. 支持多种通信方式（共享内存、Unix套接字、TCP套接字）
 16	 */
 17	public class Launcher {
 18	 private static final String VERSION = "1.0.0";
 19	 private static final String TAG = "Launcher";
 20	
 21	 private static ScreenCaptureService screenCaptureService;
 22	 private static final Config CONFIG = new Config();
 23	
 24	 /**
 25	 * 程序主入口点
 26	 *
 27	 * @param args 命令行参数
 28	 */
 29	 public static void main(String[] args) {
 30	 try {
 31	 Ln.i("[" + TAG + "] K Service v" + VERSION + " 正在启动...0");
 32	 // 设置未捕获异常处理器
 33	 Thread.setDefaultUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler() {
 34	 @Override
 35	 public void uncaughtException(Thread thread, Throwable throwable) {
 36	 Ln.e("[" + TAG + "] 线程 " + thread.getName() + " 发生未捕获异常", throwable);
 37	 cleanup();
 38	 System.exit(1);
 39	 }
 40	 });
 41	 Ln.i("[" + TAG + "] K Service v" + VERSION + " 正在启动...1");
 42	 // 解析命令行参数
 43	 if (!parseArguments(args)) {
 44	 Ln.e("[" + TAG + "] 参数解析失败，退出程序");
 45	 System.exit(1);
 46	 }
 47	 // 验证通信配置
 48	 if (!validateConfig()) {
 49	 Ln.e("[" + TAG + "] 通信配置验证失败，退出程序");
 50	 System.exit(1);
 51	 }
 52	 // 准备主循环器
 53	 Ln.d("[" + TAG + "] 准备主事件循环器");
 54	 Looper.prepareMainLooper();
 55	 initializeServer();
 56	 // 创建并启动屏幕截图服务
 57	 Ln.d("[" + TAG + "] 创建屏幕捕获服务");
 58	 screenCaptureService = new ScreenCaptureService(CONFIG);
 59	 screenCaptureService.start();
 60	 // 运行主循环
 61	 Ln.i("[" + TAG + "] 进入主事件循环");
 62	 Looper.loop();
 63	 } catch (Exception e) {
 64	 Ln.e("[" + TAG + "] 启动过程中发生致命错误", e);
 65	 cleanup();
 66	 System.exit(1);
 67	 }
 68	 }
