 70	 /**
 71	 * 解析命令行参数
 72	 *
 73	 * @param args 命令行参数数组
 74	 * @return 解析是否成功
 75	 */
 76	 private static boolean parseArguments(String[] args) {
 77	 for (int j = 0; j < args.length; j++) {
 78	 Ln.i("[" + TAG + "] args[" + j + "] = '" + args[j] + "'");
 79	 }
 80	 try {
 81	 for (int i = 0; i < args.length; i++) {
 82	 String arg = args[i];
 83	 switch (arg) {
 84	 case "--version":
 85	 case "-v":
 86	 Ln.i("[" + TAG + "] K Service v" + VERSION);
 87	 System.exit(0);
 88	 break;
 89	 case "--debug":
 90	 Ln.initLogLevel(Ln.Level.DEBUG);
 91	 Ln.d("[" + TAG + "] 调试模式已启用");
 92	 break;
 93	 case "--help":
 94	 case "-h":
 95	 printUsage();
 96	 System.exit(0);
 97	 break;
 98	 // 通信方式参数
 99	 case "--mode":
 100	 if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
 101	 String mode = args[++i].toUpperCase();
 102	 if (setMode(mode)) {
 103	 return false;
 104	 }
 105	 } else {
 106	 Ln.e("[" + TAG + "] --mode 参数缺失");
 107	 return false;
 108	 }
 109	 break;
 110	 // 共享内存相关参数
 111	 case "--libPath":
 112	 if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
 113	 CONFIG.setLibPath(args[++i]);
 114	 Ln.d("[" + TAG + "] 设置库路径: " + CONFIG.getLibPath());
 115	 } else {
 116	 Ln.e("[" + TAG + "] --libPath 参数缺失");
 117	 return false;
 118	 }
 119	 break;
 120	
 121	 // Unix套接字相关参数
 122	 case "--socketName":
 123	 if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
 124	 CONFIG.setSocketName(args[++i]);
 125	 Ln.d("[" + TAG + "] 设置套接字路径: " + CONFIG.getSocketName());
 126	 } else {
 127	 Ln.e("[" + TAG + "] --socketName 参数缺失");
 128	 return false;
 129	 }
 130	 break;
 131	
 132	 // TCP套接字相关参数
 133	 case "--tcpPort":
 134	 if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
 135	 try {
 136	 int port = Integer.parseInt(args[++i]);
 137	 CONFIG.setTcpPort(port);
 138	 Ln.d("[" + TAG + "] 设置TCP端口: " + port);
 139	 } catch (NumberFormatException e) {
 140	 Ln.e("[" + TAG + "] TCP端口格式错误: " + args[i]);
 141	 return false;
 142	 }
 143	 } else {
 144	 Ln.e("[" + TAG + "] --tcpPort 参数缺失");
 145	 return false;
 146	 }
 147	 break;
 148	
 149	 case "--tcpHost":
 150	 if (i + 1 < args.length && !args[i + 1].startsWith("-")) {
 151	 CONFIG.setTcpHost(args[++i]);
 152	 Ln.d("[" + TAG + "] 设置TCP主机: " + CONFIG.getTcpHost());
 153	 } else {
 154	 Ln.e("[" + TAG + "] --tcpHost 参数缺失");
 155	 return false;
 156	 }
 157	 break;
 158	
 159	 default:
 160	 // 处理键值对格式的参数
 161	 if (arg.startsWith("--mode=")) {
 162	 String mode = arg.substring("--mode=".length()).toUpperCase();
 163	 if (setMode(mode)) {
 164	 return false;
 165	 }
 166	 } else if (arg.startsWith("--libPath=")) {
 167	 CONFIG.setLibPath(arg.substring("--libPath=".length()));
 168	 Ln.d("[" + TAG + "] 从键值对格式设置库路径: " + CONFIG.getLibPath());
 169	 } else if (arg.startsWith("--socketName=")) {
 170	 CONFIG.setSocketName(arg.substring("--socketName=".length()));
 171	 Ln.d("[" + TAG + "] 从键值对格式设置套接字路径: " + CONFIG.getSocketName());
 172	 } else if (arg.startsWith("--tcpPort=")) {
 173	 try {
 174	 int port = Integer.parseInt(arg.substring("--tcpPort=".length()));
 175	 CONFIG.setTcpPort(port);
 176	 Ln.d("[" + TAG + "] 从键值对格式设置TCP端口: " + port);
 177	 } catch (NumberFormatException e) {
 178	 Ln.e("[" + TAG + "] TCP端口格式错误: " + arg);
 179	 return false;
 180	 }
 181	 } else if (arg.startsWith("--tcpHost=")) {
 182	 CONFIG.setTcpHost(arg.substring("--tcpHost=".length()));
 183	 Ln.d("[" + TAG + "] 从键值对格式设置TCP主机: " + CONFIG.getTcpHost());
 184	 } else if (arg.startsWith("-")) {
 185	 Ln.w("[" + TAG + "] 未知参数: " + arg);
 186	 } else {
 187	 Ln.d("[" + TAG + "] 忽略非选项参数: " + arg);
 188	 }
 189	 break;
 190	 }
 191	 }
 192	 Ln.i("[" + TAG + "] 参数解析完成");
 193	 return true;
 194	
 195	 } catch (Exception e) {
 196	 Ln.e("[" + TAG + "] 处理参数时出错", e);
 197	 return false;
 198	 }
