 201	 /**
 202	 * 验证通信配置
 203	 */
 204	 private static boolean validateConfig() {
 205	 try {
 206	 switch (CONFIG.getMode()) {
 207	 case SHARED_MEMORY:
 208	 if (CONFIG.getLibPath() == null || CONFIG.getLibPath().isEmpty()) {
 209	 Ln.e("[" + TAG + "] 共享内存模式需要指定库路径");
 210	 return false;
 211	 }
 212	 break;
 213	 case UNIX_SOCKET:
 214	 if (CONFIG.getSocketName() == null || CONFIG.getSocketName().isEmpty()) {
 215	 Ln.e("[" + TAG + "] Unix套接字模式需要指定套接字路径");
 216	 return false;
 217	 }
 218	 break;
 219	 case TCP_SOCKET:
 220	 if (CONFIG.getTcpPort() <= 0 || CONFIG.getTcpPort() > 65535) {
 221	 Ln.e("[" + TAG + "] TCP套接字模式需要指定有效端口号(1-65535)");
 222	 return false;
 223	 }
 224	 break;
 225	 }
 226	 return true;
 227	 } catch (Exception e) {
 228	 Ln.e("[" + TAG + "] 验证通信配置时出错", e);
 229	 return false;
 230	 }
 231	 }
