 233	 /**
 234	 * 设置通信方式
 235	 *
 236	 * @param mode 通信方式字符串
 237	 * @return true表示设置成功，false表示设置失败
 238	 */
 239	 private static boolean setMode(String mode) {
 240	 try {
 241	 Mode commMode = Mode.valueOf(mode);
 242	 CONFIG.setMode(commMode);
 243	 Ln.d("[" + TAG + "] 设置通信方式: " + commMode);
 244	 return false;
 245	 } catch (IllegalArgumentException e) {
 246	 Ln.e("[" + TAG + "] 无效的通信方式: " + mode + "，支持的方式: SHARED_MEMORY, UNIX_SOCKET, TCP_SOCKET");
 247	 return true;
 248	 }
 249	 }
