 286	 System.out.println(" --help, -h 显示此帮助信息");
 287	 System.out.println(" --debug 启用调试模式");
 288	 System.out.println(" --mode <MODE> 设置通信方式 (SHARED_MEMORY|UNIX_SOCKET|TCP_SOCKET)");
 289	 System.out.println();
 290	 System.out.println("共享内存模式选项:");
 291	 System.out.println(" --libPath <PATH> 指定native库路径");
 292	 System.out.println();
 293	 System.out.println("Unix套接字模式选项:");
 294	 System.out.println(" --socketName <NAME> 指定套接字文件路径 (默认: k-server.socket)");
 295	 System.out.println();
 296	 System.out.println("TCP套接字模式选项:");
 297	 System.out.println(" --tcpPort <PORT> 指定TCP端口号 (默认: 8888)");
 298	 System.out.println(" --tcpHost <HOST> 指定TCP主机地址 (默认: 127.0.0.1)");
 299	 System.out.println();
 300	 System.out.println("示例:");
 301	 System.out.println(" # 使用共享内存模式");
 302	 System.out.println(" CLASSPATH=/data/app/com.example.app/base.apk app_process /system/bin " + Launcher.class.getName() + " --mode=SHARED_MEMORY --libPath=/data/local/tmp");
 303	 System.out.println();
 304	 System.out.println(" # 使用Unix套接字模式");
 305	 System.out.println(" CLASSPATH=/data/app/com.example.app/base.apk app_process /system/bin " + Launcher.class.getName() + " --mode=UNIX_SOCKET --socketPath=/data/local/tmp/kserver.sock");
 306	 System.out.println();
 307	 System.out.println(" # 使用TCP套接字模式");
 308	 System.out.println(" CLASSPATH=/data/app/com.example.app/base.apk app_process /system/bin " + Launcher.class.getName() + " --mode=TCP_SOCKET --tcpPort=8888");
 309	 }
