 144	 return -1;
 145	 }
 146	
 147	 // 设置执行权限
 148	 chmod(so_file, 0755);
 149	
 150	 printf("✅ 文件释放完成\n");
 151	 printf(" DEX: %s (%u 字节)\n", dex_path, k_server_dex_len);
 152	 printf(" SO: %s (%u 字节)\n", so_file, libserver_k_so_len);
 153	
 154	 return 0;
