 18	// Unix套接字服务器初始化
 19	int unix_server_initialize(server_config_t* config) {
 20	 if (!config) {
 21	 LOG_ERROR(UNIX_SERVER_LOG_TAG, "配置参数为空");
 22	 return -1;
 23	 }
 24	
 25	 LOG_INFO(UNIX_SERVER_LOG_TAG, "初始化Unix套接字服务器");
 26	
 27	 // 检查socket名称
 28	 if (strlen(config->socket_name) == 0) {
 29	 LOG_ERROR(UNIX_SERVER_LOG_TAG, "套接字名称为空");
 30	 return -1;
 31	 }
 32	
 33	 // 初始化客户端连接数组
 34	 for (int i = 0; i < MAX_CLIENTS; i++) {
 35	 g_server_ctx.server_data.unix_socket.client_fds[i] = -1;
 36	 }
 37	 g_server_ctx.server_data.unix_socket.client_count = 0;
 38	 g_server_ctx.server_data.unix_socket.server_fd = -1;
 39	
 40	 LOG_INFO(UNIX_SERVER_LOG_TAG, "Unix套接字服务器初始化成功，套接字名称: %s",
 41	 config->socket_name);
 42	
 43	 return 0;
 44	}
 45	
 46	// Unix套接字服务器启动
 47	int unix_server_start(void) {
 48	 LOG_INFO(UNIX_SERVER_LOG_TAG, "启动Unix套接字服务器");
 49	
 50	 // 创建socket
 51	 int server_fd = socket(AF_UNIX, SOCK_STREAM, 0);
 52	 if (server_fd < 0) {
 53	 LOG_ERROR(UNIX_SERVER_LOG_TAG, "创建套接字失败: %s", strerror(errno));
 54	 return -1;
 55	 }
 56	
 57	 // 设置socket为非阻塞模式
 58	 int flags = fcntl(server_fd, F_GETFL, 0);
 59	 if (flags < 0 || fcntl(server_fd, F_SETFL, flags | O_NONBLOCK) < 0) {
 60	 LOG_WARN(UNIX_SERVER_LOG_TAG, "设置套接字非阻塞模式失败: %s", strerror(errno));
 61	 }
 62	
 63	 // 构建socket路径
 64	 char socket_path[256];
 65	 snprintf(socket_path, sizeof(socket_path), "%s%s",
 66	 UNIX_SOCKET_PATH_PREFIX, g_server_ctx.config.socket_name);
 67	
 68	 // 删除已存在的socket文件
 69	 unlink(socket_path);
 70	
 71	 // 绑定socket
 72	 struct sockaddr_un addr;
 73	 memset(&addr, 0, sizeof(addr));
 74	 addr.sun_family = AF_UNIX;
 75	 strncpy(addr.sun_path, socket_path, sizeof(addr.sun_path) - 1);
 76	
 77	 if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
 78	 LOG_ERROR(UNIX_SERVER_LOG_TAG, "绑定套接字到 %s 失败: %s",
 79	 socket_path, strerror(errno));
 80	 close(server_fd);
 81	 return -1;
 82	 }
 83	
 84	 // 监听连接
 85	 if (listen(server_fd, MAX_CLIENTS) < 0) {
 86	 LOG_ERROR(UNIX_SERVER_LOG_TAG, "监听套接字失败: %s", strerror(errno));
 87	 close(server_fd);
 88	 unlink(socket_path);
 89	 return -1;
 90	 }
 91	
 92	 // 保存服务器文件描述符
 93	 g_server_ctx.server_data.unix_socket.server_fd = server_fd;
 94	
 95	 LOG_INFO(UNIX_SERVER_LOG_TAG, "Unix套接字服务器启动成功，路径: %s", socket_path);
 96	 return 0;
 97	}
 98	
 99	// Unix套接字服务器停止
 100	int unix_server_stop(void) {
 101	 LOG_INFO(UNIX_SERVER_LOG_TAG, "停止Unix套接字服务器");
 102	
 103	 // 关闭所有客户端连接
 104	 for (int i = 0; i < MAX_CLIENTS; i++) {
 105	 if (g_server_ctx.server_data.unix_socket.client_fds[i] >= 0) {
 106	 unix_server_close_client(i);
 107	 }
 108	 }
 109	
 110	 // 关闭服务器socket
 111	 if (g_server_ctx.server_data.unix_socket.server_fd >= 0) {
 112	 close(g_server_ctx.server_data.unix_socket.server_fd);
 113	 g_server_ctx.server_data.unix_socket.server_fd = -1;
 114	 }
 115	
 116	 // 删除socket文件
 117	 char socket_path[256];
 118	 snprintf(socket_path, sizeof(socket_path), "%s%s",
 119	 UNIX_SOCKET_PATH_PREFIX, g_server_ctx.config.socket_name);
 120	 unlink(socket_path);
 121	
 122	 g_server_ctx.server_data.unix_socket.client_count = 0;
 123	
 124	 LOG_INFO(UNIX_SERVER_LOG_TAG, "Unix套接字服务器已停止");
 125	 return 0;
 126	}
