 128	// Unix套接字服务器写入数据
 129	int unix_server_write_data(const uint8_t* data, size_t size) {
 130	 if (!data || size == 0) {
 131	 LOG_WARN(UNIX_SERVER_LOG_TAG, "数据参数无效");
 132	 return -1;
 133	 }
 134	
 135	 // 接受新的客户端连接
 136	 unix_server_accept_clients();
 137	
 138	 // 发送数据到所有客户端
 139	 return unix_server_send_to_clients(data, size);
 140	}
