 142	// Unix套接字服务器清理
 143	int unix_server_cleanup(void) {
 144	 LOG_INFO(UNIX_SERVER_LOG_TAG, "清理Unix套接字服务器");
 145	
 146	 // 停止服务器
 147	 unix_server_stop();
 148	
 149	 LOG_INFO(UNIX_SERVER_LOG_TAG, "Unix套接字服务器清理完成");
 150	 return 0;
 151	}
