 153	// 接受客户端连接
 154	int unix_server_accept_clients(void) {
 155	 if (g_server_ctx.server_data.unix_socket.server_fd < 0) {
 156	 return -1;
 157	 }
 158	 
 159	 // 使用select检查是否有新连接
 160	 fd_set read_fds;
 161	 struct timeval timeout = {0, 0}; // 非阻塞
 162	 
 163	 FD_ZERO(&read_fds);
 164	 FD_SET(g_server_ctx.server_data.unix_socket.server_fd, &read_fds);
 165	 
 166	 int result = select(g_server_ctx.server_data.unix_socket.server_fd + 1, &read_fds, NULL, NULL, &timeout);
 167	 if (result <= 0) {
 168	 return 0; // 没有新连接或出错
 169	 }
 170	 
 171	 if (FD_ISSET(g_server_ctx.server_data.unix_socket.server_fd, &read_fds)) {
 172	 // 接受新连接
 173	 int client_fd = accept(g_server_ctx.server_data.unix_socket.server_fd, NULL, NULL);
 174	 if (client_fd < 0) {
 175	 if (errno != EAGAIN && errno != EWOULDBLOCK) {
 176	 LOG_WARN(UNIX_SERVER_LOG_TAG, "接受客户端连接失败: %s", strerror(errno));
 177	 }
 178	 return -1;
 179	 }
 180	
 181	 // 查找空闲的客户端槽位
 182	 for (int i = 0; i < MAX_CLIENTS; i++) {
 183	 if (g_server_ctx.server_data.unix_socket.client_fds[i] < 0) {
 184	 g_server_ctx.server_data.unix_socket.client_fds[i] = client_fd;
 185	 g_server_ctx.server_data.unix_socket.client_count++;
 186	 LOG_INFO(UNIX_SERVER_LOG_TAG, "新客户端连接，fd: %d，总客户端数: %d",
 187	 client_fd, g_server_ctx.server_data.unix_socket.client_count);
 188	 return 0;
 189	 }
 190	 }
 191	
 192	 // 没有空闲槽位，关闭连接
 193	 LOG_WARN(UNIX_SERVER_LOG_TAG, "已达到最大客户端数量，拒绝连接");
 194	 close(client_fd);
 195	 }
 196	 
 197	 return 0;
 198	}
 199	
 200	// 发送数据到所有客户端
 201	int unix_server_send_to_clients(const uint8_t* data, size_t size) {
 202	 if (g_server_ctx.server_data.unix_socket.client_count == 0) {
 203	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "没有客户端连接，跳过数据发送");
 204	 return 0;
 205	 }
 206	
 207	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "向 %d 个客户端发送数据，大小: %zu 字节",
 208	 g_server_ctx.server_data.unix_socket.client_count, size);
 209	
 210	 // 准备数据包（4字节长度头 + 数据）
 211	 uint32_t data_length = (uint32_t)size;
 212	 uint8_t header[4];
 213	 header[0] = (uint8_t)(data_length & 0xFF);
 214	 header[1] = (uint8_t)((data_length >> 8) & 0xFF);
 215	 header[2] = (uint8_t)((data_length >> 16) & 0xFF);
 216	 header[3] = (uint8_t)((data_length >> 24) & 0xFF);
 217	
 218	 int success_count = 0;
 219	
 220	 for (int i = 0; i < MAX_CLIENTS; i++) {
 221	 int client_fd = g_server_ctx.server_data.unix_socket.client_fds[i];
 222	 if (client_fd < 0) {
 223	 continue;
 224	 }
 225	
 226	 // 发送长度头
 227	 ssize_t sent = send(client_fd, header, 4, MSG_NOSIGNAL);
 228	 if (sent != 4) {
 229	 LOG_WARN(UNIX_SERVER_LOG_TAG, "向客户端 %d 发送数据头失败: %s",
 230	 client_fd, strerror(errno));
 231	 unix_server_close_client(i);
 232	 continue;
 233	 }
 234	
 235	 // 发送数据
 236	 sent = send(client_fd, data, size, MSG_NOSIGNAL);
 237	 if (sent != (ssize_t)size) {
 238	 LOG_WARN(UNIX_SERVER_LOG_TAG, "向客户端 %d 发送数据失败: %s",
 239	 client_fd, strerror(errno));
 240	 unix_server_close_client(i);
 241	 continue;
 242	 }
 243	
 244	 success_count++;
 245	 }
 246	
 247	 LOG_DEBUG(UNIX_SERVER_LOG_TAG, "成功向 %d 个客户端发送数据", success_count);
 248	 return success_count > 0 ? 0 : -1;
 249	}
 250	
 251	// 关闭客户端连接
 252	void unix_server_close_client(int client_index) {
 253	 if (client_index < 0 || client_index >= MAX_CLIENTS) {
 254	 return;
 255	 }
 256	
 257	 int client_fd = g_server_ctx.server_data.unix_socket.client_fds[client_index];
 258	 if (client_fd >= 0) {
 259	 LOG_INFO(UNIX_SERVER_LOG_TAG, "关闭客户端连接，fd: %d", client_fd);
 260	 close(client_fd);
 261	 g_server_ctx.server_data.unix_socket.client_fds[client_index] = -1;
 262	 g_server_ctx.server_data.unix_socket.client_count--;
 263	 }
 264	}
