 25	// Unix套接字客户端连接
 26	int unix_client_connect(client_config_t* config) {
 27	 if (!config) {
 28	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "配置参数为空");
 29	 return -1;
 30	 }
 31	 
 32	 LOG_INFO(UNIX_CLIENT_LOG_TAG, "连接Unix套接字");
 33	 
 34	 // 检查socket名称
 35	 if (strlen(config->socket_name) == 0) {
 36	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "套接字名称为空");
 37	 return -1;
 38	 }
 39	 
 40	 // 创建socket
 41	 int client_fd = socket(AF_UNIX, SOCK_STREAM, 0);
 42	 if (client_fd < 0) {
 43	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "创建套接字失败: %s", strerror(errno));
 44	 return -1;
 45	 }
 46	 
 47	 // 设置socket超时
 48	 struct timeval timeout;
 49	 timeout.tv_sec = READ_TIMEOUT / 1000;
 50	 timeout.tv_usec = (READ_TIMEOUT % 1000) * 1000;
 51	 if (setsockopt(client_fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0) {
 52	 LOG_WARN(UNIX_CLIENT_LOG_TAG, "设置接收超时失败: %s", strerror(errno));
 53	 }
 54	 
 55	 // 构建socket路径
 56	 char socket_path[256];
 57	 snprintf(socket_path, sizeof(socket_path), "%s%s", 
 58	 UNIX_SOCKET_PATH_PREFIX, config->socket_name);
 59	 
 60	 // 连接socket
 61	 struct sockaddr_un addr;
 62	 memset(&addr, 0, sizeof(addr));
 63	 addr.sun_family = AF_UNIX;
 64	 strncpy(addr.sun_path, socket_path, sizeof(addr.sun_path) - 1);
 65	 
 66	 if (connect(client_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
 67	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "连接套接字到 %s 失败: %s", 
 68	 socket_path, strerror(errno));
 69	 close(client_fd);
 70	 return -1;
 71	 }
 72	 
 73	 // 保存客户端文件描述符
 74	 g_client_ctx.client_data.unix_socket.socket_fd = client_fd;
 75	 
 76	 LOG_INFO(UNIX_CLIENT_LOG_TAG, "Unix套接字连接成功，路径: %s", socket_path);
 77	 return 0;
 78	}
 79	
 80	// Unix套接字客户端断开连接
 81	void unix_client_disconnect(void) {
 82	 LOG_INFO(UNIX_CLIENT_LOG_TAG, "断开Unix套接字连接");
 83	 
 84	 // 关闭客户端socket
 85	 if (g_client_ctx.client_data.unix_socket.socket_fd >= 0) {
 86	 close(g_client_ctx.client_data.unix_socket.socket_fd);
 87	 g_client_ctx.client_data.unix_socket.socket_fd = -1;
 88	 }
 89	 
 90	 LOG_INFO(UNIX_CLIENT_LOG_TAG, "Unix套接字连接已断开");
 91	}
