 94	client_response_t* unix_client_take_screenshot(void) {
 95	 long start_time = get_current_time_ms();
 96	 
 97	 client_response_t* response = malloc(sizeof(client_response_t));
 98	 if (!response) {
 99	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "分配响应结构体内存失败");
 100	 return NULL;
 101	 }
 102	 
 103	 // 初始化响应
 104	 memset(response, 0, sizeof(client_response_t));
 105	 response->success = false;
 106	 response->data = NULL;
 107	 response->data_size = 0;
 108	 
 109	 if (g_client_ctx.client_data.unix_socket.socket_fd < 0) {
 110	 strcpy(response->message, "套接字未连接");
 111	 response->processing_time = get_current_time_ms() - start_time;
 112	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "套接字未连接");
 113	 return response;
 114	 }
 115	 
 116	 LOG_DEBUG(UNIX_CLIENT_LOG_TAG, "从Unix套接字读取截图数据");
 117	 
 118	 // 读取数据
 119	 uint8_t* data = NULL;
 120	 size_t data_size = 0;
 121	 int result = unix_client_read_data(&data, &data_size);
 122	 
 123	 long processing_time = get_current_time_ms() - start_time;
 124	 
 125	 if (result == 0 && data && data_size > 0) {
 126	 response->success = true;
 127	 snprintf(response->message, sizeof(response->message), 
 128	 "截图读取成功，耗时: %ld ms", processing_time);
 129	 response->data = data;
 130	 response->data_size = data_size;
 131	 response->processing_time = processing_time;
 132	 
 133	 LOG_DEBUG(UNIX_CLIENT_LOG_TAG, "成功从Unix套接字读取数据，大小: %zu 字节，耗时: %ld ms", 
 134	 data_size, processing_time);
 135	 } else {
 136	 snprintf(response->message, sizeof(response->message), 
 137	 "读取失败，错误代码: %d", result);
 138	 response->processing_time = processing_time;
 139	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "从Unix套接字读取数据失败，错误代码: %d", result);
 140	 
 141	 if (data) {
 142	 free(data);
 143	 }
 144	 }
 145	 
 146	 return response;
 147	}
