 149	// 读取数据
 150	int unix_client_read_data(uint8_t** data, size_t* size) {
 151	 int client_fd = g_client_ctx.client_data.unix_socket.socket_fd;
 152	 
 153	 // 读取4字节长度头
 154	 uint8_t header[4];
 155	 ssize_t bytes_read = 0;
 156	 while (bytes_read < 4) {
 157	 ssize_t read_result = recv(client_fd, header + bytes_read, 4 - bytes_read, 0);
 158	 if (read_result <= 0) {
 159	 if (read_result == 0) {
 160	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "连接已断开");
 161	 } else {
 162	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "读取数据头失败: %s", strerror(errno));
 163	 }
 164	 return -1;
 165	 }
 166	 bytes_read += read_result;
 167	 }
 168	 
 169	 // 解析数据长度（小端序）
 170	 uint32_t data_length = (uint32_t)header[0] | 
 171	 ((uint32_t)header[1] << 8) | 
 172	 ((uint32_t)header[2] << 16) | 
 173	 ((uint32_t)header[3] << 24);
 174	 
 175	 LOG_DEBUG(UNIX_CLIENT_LOG_TAG, "准备读取数据，长度: %u 字节", data_length);
 176	 
 177	 if (data_length == 0) {
 178	 *data = NULL;
 179	 *size = 0;
 180	 return 0;
 181	 }
 182	 
 183	 if (data_length > MAX_DATA_SIZE) {
 184	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "数据长度过大: %u", data_length);
 185	 return -1;
 186	 }
 187	 
 188	 // 分配内存并读取数据
 189	 uint8_t* buffer = malloc(data_length);
 190	 if (!buffer) {
 191	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "分配数据缓冲区内存失败");
 192	 return -1;
 193	 }
 194	 
 195	 bytes_read = 0;
 196	 while (bytes_read < data_length) {
 197	 ssize_t read_result = recv(client_fd, buffer + bytes_read, data_length - bytes_read, 0);
 198	 if (read_result <= 0) {
 199	 if (read_result == 0) {
 200	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "连接已断开");
 201	 } else {
 202	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "读取数据失败: %s", strerror(errno));
 203	 }
 204	 free(buffer);
 205	 return -1;
 206	 }
 207	 bytes_read += read_result;
 208	 }
 209	 
 210	 *data = buffer;
 211	 *size = data_length;
 212	 return 0;
 213	}
