 435	 /**
 436	 * 处理图像数据并写入共享内存
 437	 *
 438	 * @param image 要处理的图像
 439	 */
 440	 private void processImageData(Image image) {
 441	 try {
 442	 Image.Plane plane = image.getPlanes()[0];
 443	 ByteBuffer buffer = plane.getBuffer();
 444	 if (buffer == null) {
 445	 Ln.w("[数据处理] 图像缓冲区为空");
 446	 return;
 447	 }
 448	 // 获取图像参数
 449	 int imageWidth = image.getWidth();
 450	 int imageHeight = image.getHeight();
 451	 int pixelStride = plane.getPixelStride(); // RGBA_8888通常是4字节
 452	 int rowStride = plane.getRowStride(); // 每行实际字节数
 453	 int rowPadding = rowStride - pixelStride * imageWidth; // 行填充字节数
 454	
 455	 // 计算清理后的数据大小
 456	 int cleanDataSize = imageWidth * imageHeight * 4;
 457	 int totalSize = cleanDataSize + HEADER_SIZE_BYTES;
 458	 if (reusableByteArray.length < totalSize) {
 459	 reusableByteArray = new byte[totalSize];
 460	 }
 461	 // 写入正确的头部信息（实际图像尺寸）
 462	 ByteBuffer headerBuffer = ByteBuffer.wrap(reusableByteArray, 0, HEADER_SIZE_BYTES);
 463	 headerBuffer.order(ByteOrder.LITTLE_ENDIAN);
 464	 headerBuffer.putInt(imageWidth); // 实际宽度
 465	 headerBuffer.putInt(imageHeight); // 实际高度
 466	 // 去除行填充，只复制实际像素数据
 467	 if (rowPadding == 0) {
 468	 // 没有行填充，直接复制
 469	 buffer.get(reusableByteArray, HEADER_SIZE_BYTES, cleanDataSize);
 470	 } else {
 471	 // 有行填充，逐行复制
 472	 byte[] rowBuffer = new byte[rowStride];
 473	 int destOffset = HEADER_SIZE_BYTES;
 474	 for (int y = 0; y < imageHeight; y++) {
 475	 buffer.get(rowBuffer, 0, rowStride);
 476	 System.arraycopy(rowBuffer, 0, reusableByteArray, destOffset, imageWidth * 4);
 477	 destOffset += imageWidth * 4;
 478	 }
 479	 }
 480	 // 通过通信通道写入数据
 481	 try {
 482	 int success = Server.writeData(reusableByteArray);
 483	 if (success == 0) {
 484	 Ln.d("[" + TAG + "] 成功写入到通信通道 (" + imageWidth + "x" + imageHeight + ")，数据大小: " + totalSize + " 字节");
 485	 } else {
 486	 Ln.e("[" + TAG + "] 写入通信通道失败");
 487	 }
 488	 } catch (Exception e) {
 489	 Ln.e("[" + TAG + "] 写入通信通道时出错", e);
 490	 }
 491	 } catch (Exception e) {
 492	 Ln.e("[数据处理] 处理图像数据时出错", e);
 493	 }
 494	 }
