 97	client_response_t* unix_client_take_screenshot(void) {
 98	 long start_time = get_current_time_ms();
 99	 
 100	 client_response_t* response = malloc(sizeof(client_response_t));
 101	 if (!response) {
 102	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "分配响应结构体内存失败");
 103	 return NULL;
 104	 }
 105	 
 106	 // 初始化响应
 107	 memset(response, 0, sizeof(client_response_t));
 108	 response->success = false;
 109	 response->data = NULL;
 110	 response->data_size = 0;
 111	 
 112	 if (g_client_ctx.client_data.unix_socket.socket_fd < 0) {
 113	 strcpy(response->message, "套接字未连接");
 114	 response->processing_time = get_current_time_ms() - start_time;
 115	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "套接字未连接");
 116	 return response;
 117	 }
