 26	int unix_client_connect(client_config_t* config) {
 27	 if (!config) {
 28	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "配置参数为空");
 29	 return -1;
 30	 }
 31	 
 32	 LOG_INFO(UNIX_CLIENT_LOG_TAG, "连接Unix套接字");
 33	 
 34	 // 检查socket名称
 35	 if (strlen(config->socket_name) == 0) {
 36	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "套接字名称为空");
 37	 return -1;
 38	 }
 39	 
 40	 // 创建socket
 41	 int client_fd = socket(AF_UNIX, SOCK_STREAM, 0);
 42	 if (client_fd < 0) {
 43	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "创建套接字失败: %s", strerror(errno));
 44	 return -1;
 45	 }
 46	 
 47	 // 设置socket超时
 48	 struct timeval timeout;
 49	 timeout.tv_sec = READ_TIMEOUT / 1000;
 50	 timeout.tv_usec = (READ_TIMEOUT % 1000) * 1000;
 51	 if (setsockopt(client_fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0) {
 52	 LOG_WARN(UNIX_CLIENT_LOG_TAG, "设置接收超时失败: %s", strerror(errno));
 53	 }
 54	 
 55	 // 使用Abstract Unix Socket连接
 56	 LOG_DEBUG(UNIX_CLIENT_LOG_TAG, "连接到Abstract Unix Socket: @%s", config->socket_name);
 57	
 58	 struct sockaddr_un addr;
 59	 memset(&addr, 0, sizeof(addr));
 60	 addr.sun_family = AF_UNIX;
 61	
 62	 // Abstract socket: 第一个字符为'\0'，后面跟socket名称
 63	 addr.sun_path[0] = '\0';
 64	 strncpy(addr.sun_path + 1, config->socket_name, sizeof(addr.sun_path) - 2);
 65	
 66	 // Abstract socket的长度计算
 67	 int addr_len = sizeof(addr.sun_family) + 1 + strlen(config->socket_name);
 68	
 69	 if (connect(client_fd, (struct sockaddr*)&addr, addr_len) < 0) {
 70	 LOG_ERROR(UNIX_CLIENT_LOG_TAG, "连接Abstract套接字 @%s 失败: %s",
 71	 config->socket_name, strerror(errno));
 72	 close(client_fd);
 73	 return -1;
 74	 }
