 28	int asm_create(size_t size) {
 29	 size_t total_size = size + 16;
 30	 LOG_INFO(SM_LOG_TAG, "创建共享内存文件，大小: %zu 字节", total_size);
 31	 (void) asm_cleanup();
 32	 (void) unlink(SM_FILE_PATH);
 33	 int fd = open(SM_FILE_PATH, O_CREAT | O_RDWR, 0666);
 34	 if (fd < 0) {
 35	 LOG_ERROR(SM_LOG_TAG, "创建共享内存失败");
 36	 return -1;
 37	 }
 38	 if (ftruncate(fd, (off_t) total_size) < 0) {
 39	 LOG_ERROR(SM_LOG_TAG, "创建共享内存失败");
 40	 close(fd);
 41	 (void) unlink(SM_FILE_PATH);
 42	 return -1;
 43	 }
 44	 LOG_DEBUG(SM_LOG_TAG, "创建共享内存成功");
 45	 // 映射内存
 46	 void *base = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
 47	 if (base == MAP_FAILED) {
 48	 close(fd);
 49	 (void) unlink(SM_FILE_PATH); // 忽略返回值
 50	 return -1;
 51	 }
 52	 // 设置全局变量
 53	 g_asm_fd = fd;
 54	 g_asm_base = base;
 55	 g_asm_timestamp = (uint64_t *) base;
 56	 g_asm_data_size = (uint64_t *) ((unsigned char *) base + 8);
 57	 g_asm_data_ptr = (unsigned char *) base + 16;
 58	 LOG_INFO(SM_LOG_TAG, "共享内存创建成功");
 59	 return 0;
 60	}
 61	
 62	int asm_connect(size_t size) {
 63	 size_t total_size = size + 16;
 64	 LOG_INFO(SM_LOG_TAG, "连接共享内存文件，大小: %zu 字节", total_size);
 65	 int fd = open(SM_FILE_PATH, O_RDWR);
 66	 if (fd < 0) {
 67	 LOG_ERROR(SM_LOG_TAG, "打开共享内存文件失败");
 68	 return -1;
 69	 }
 70	 // 映射内存
 71	 void *base = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
 72	 if (base == MAP_FAILED) {
 73	 close(fd);
 74	 return -1;
 75	 }
 76	 // 设置全局变量
 77	 g_asm_fd = fd;
 78	 g_asm_base = base;
 79	 g_asm_timestamp = (uint64_t *) base;
 80	 g_asm_data_size = (uint64_t *) ((unsigned char *) base + 8);
 81	 g_asm_data_ptr = (unsigned char *) base + 16;
 82	 LOG_INFO(SM_LOG_TAG, "共享内存连接成功");
 83	 return 0;
 84	}
 85	
 86	int asm_write(const void *data, size_t size) {
 87	 if (!data || !g_asm_base || !g_asm_data_ptr || !g_asm_data_size || !g_asm_timestamp) {
 88	 return -1;
 89	 }
 90	 // 检查数据大小合理性
 91	 if (size > 50 * 1024 * 1024) { // 50MB限制
 92	 LOG_ERROR(SM_LOG_TAG, "写入数据大小过大: %zu", size);
 93	 return -1;
 94	 }
 95	 memcpy(g_asm_data_ptr, data, size);
 96	 __sync_synchronize();
 97	 *g_asm_data_size = (uint64_t) size;
 98	 __sync_synchronize();
 99	 *g_asm_timestamp = get_timestamp_ms();
 100	
 101	 return 0;
 102	}
 103	
 104	int asm_read(uint8_t **data, size_t *data_size) {
 105	 if (!data || !data_size) {
 106	 LOG_ERROR(SM_LOG_TAG, "参数无效");
 107	 return -1;
 108	 }
 109	
 110	 if (!g_asm_base || !g_asm_timestamp || !g_asm_data_size || !g_asm_data_ptr) {
 111	 LOG_ERROR(SM_LOG_TAG, "共享内存未初始化");
 112	 return -1;
 113	 }
 114	
 115	 // 读取当前时间戳和数据大小
 116	 uint64_t current_ts = *g_asm_timestamp;
 117	 uint64_t current_size = *g_asm_data_size;
 118	
 119	 // 检查是否有新数据
 120	 if (current_ts <= g_asm_last_read_ts) {
 121	 *data = NULL;
 122	 *data_size = 0;
 123	 return 1; // 没有新数据
 124	 }
 125	
 126	 if (current_size == 0) {
 127	 *data = NULL;
 128	 *data_size = 0;
 129	 g_asm_last_read_ts = current_ts;
 130	 return 1; // 数据为空
 131	 }
 132	
 133	 // 分配内存并复制数据
 134	 uint8_t *buffer = malloc(current_size);
 135	 if (!buffer) {
 136	 LOG_ERROR(SM_LOG_TAG, "分配内存失败");
 137	 return -1;
 138	 }
 139	
 140	 memcpy(buffer, g_asm_data_ptr, current_size);
 141	
 142	 *data = buffer;
 143	 *data_size = current_size;
 144	 g_asm_last_read_ts = current_ts;
 145	
 146	 LOG_DEBUG(SM_LOG_TAG, "成功读取数据，大小: %zu 字节", current_size);
 147	 return 0;
 148	}
 149	
 150	int asm_cleanup(void) {
 151	 int result = 0;
 152	
 153	 if (g_asm_base) {
 154	 // 重置指针
 155	 g_asm_base = NULL;
 156	 g_asm_timestamp = NULL;
 157	 g_asm_data_size = NULL;
 158	 g_asm_data_ptr = NULL;
 159	 }
 160	
 161	 if (g_asm_fd >= 0) {
 162	 if (close(g_asm_fd) != 0) {
 163	 result = -1;
 164	 }
 165	 g_asm_fd = -1;
 166	 }
 167	
 168	 // 删除共享内存文件（忽略错误，因为文件可能不存在）
 169	 (void) unlink(SM_FILE_PATH);
 170	
 171	 // 重置读取时间戳
 172	 g_asm_last_read_ts = 0;
 173	
 174	 return result;
 175	}
